/**
 * Construction QA Centre Page
 * Main dashboard for civil, optical, and splicing quality assurance.
 *
 * Layout: Stats cards + discipline tabs + filter bar + feature data grid
 * Pattern: Follows Activate QA Centre and QField QA Dashboard conventions
 */

'use client';

import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { useRouter } from 'next/router';
import {
  RefreshCw,
  CheckCircle,
  XCircle,
  Clock,
  AlertTriangle,
  HardHat,
  Cable,
  CircleDot,
  Search,
} from 'lucide-react';
import { StatsGrid } from '@/components/dashboard/EnhancedStatCard';
import type { EnhancedStatCardProps } from '@/components/dashboard/EnhancedStatCard';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { log } from '@/lib/logger';

type Discipline = 'civil' | 'optical' | 'splicing';
type WorkflowStatus = 'pending' | 'in_review' | 'approved' | 'rejected' | 'rework_needed' | 'escalated' | 'unidentified';

interface FeatureRow {
  id: string;
  feature_id: string;
  feature_type: string;
  discipline: Discipline;
  zone_no: number | null;
  pon_no: number | null;
  photo_count: number;
  vlm_confidence: number | null;
  vlm_status: string;
  workflow_status: WorkflowStatus;
  qa_decision: string | null;
  priority: string;
  assigned_to: string | null;
  created_at: string;
  updated_at: string;
  project_name?: string;
}

interface Stats {
  total: number;
  pending: number;
  approved: number;
  rejected: number;
  rework_needed: number;
  escalated: number;
  unidentified: number;
}

interface Filters {
  projectId: string;
  discipline: Discipline;
  zoneNo: string;
  ponNo: string;
  workflowStatus: string;
  priority: string;
  search: string;
  page: number;
  pageSize: number;
}

const DISCIPLINE_TABS: { key: Discipline; label: string; icon: typeof HardHat }[] = [
  { key: 'civil', label: 'Poles (Civil)', icon: HardHat },
  { key: 'optical', label: 'Cable Spans (Optical)', icon: Cable },
  { key: 'splicing', label: 'Dome Joints (Splicing)', icon: CircleDot },
];

export function ConstructionQaCentrePage() {
  const router = useRouter();

  // State
  const [filters, setFilters] = useState<Filters>({
    projectId: '',
    discipline: 'civil',
    zoneNo: '',
    ponNo: '',
    workflowStatus: '',
    priority: '',
    search: '',
    page: 1,
    pageSize: 50,
  });
  const [features, setFeatures] = useState<FeatureRow[]>([]);
  const [stats, setStats] = useState<Stats>({
    total: 0, pending: 0, approved: 0, rejected: 0, rework_needed: 0, escalated: 0, unidentified: 0,
  });
  const [projects, setProjects] = useState<{ id: string; name: string }[]>([]);
  const [loading, setLoading] = useState(false);
  const [totalCount, setTotalCount] = useState(0);
  const [totalPages, setTotalPages] = useState(0);
  const [lastRefresh, setLastRefresh] = useState<Date | null>(null);
  const [showFilters, setShowFilters] = useState(false);

  // Fetch projects list
  useEffect(() => {
    async function loadProjects() {
      try {
        const res = await fetch('/api/construction-qa/features?action=projects', {
          credentials: 'include',
        });
        if (res.ok) {
          const data = await res.json();
          setProjects(data.data?.projects || []);
        }
      } catch (err) {
        log.error('Failed to load projects', { module: 'construction-qa', error: (err as Error).message }, 'construction-qa');
      }
    }
    loadProjects();
  }, []);

  // Fetch features and stats
  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (filters.projectId) params.set('projectId', filters.projectId);
      params.set('discipline', filters.discipline);
      if (filters.zoneNo) params.set('zoneNo', filters.zoneNo);
      if (filters.ponNo) params.set('ponNo', filters.ponNo);
      if (filters.workflowStatus) params.set('workflowStatus', filters.workflowStatus);
      if (filters.priority) params.set('priority', filters.priority);
      if (filters.search) params.set('search', filters.search);
      params.set('page', String(filters.page));
      params.set('pageSize', String(filters.pageSize));

      const res = await fetch(`/api/construction-qa/features?${params.toString()}`, {
        credentials: 'include',
      });

      if (res.ok) {
        const data = await res.json();
        setFeatures(data.data?.features || []);
        setStats(data.data?.stats || { total: 0, pending: 0, approved: 0, rejected: 0, rework_needed: 0, escalated: 0, unidentified: 0 });
        setTotalCount(data.data?.pagination?.total || 0);
        setTotalPages(data.data?.pagination?.totalPages || 0);
        setLastRefresh(new Date());
      }
    } catch (err) {
      log.error('Failed to fetch features', { module: 'construction-qa', error: (err as Error).message }, 'construction-qa');
    } finally {
      setLoading(false);
    }
  }, [filters]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Stats cards
  const statCards: EnhancedStatCardProps[] = useMemo(() => [
    {
      title: 'Total Features',
      subtitle: 'All features',
      value: stats.total,
      description: `Total ${filters.discipline} features across all projects`,
      icon: HardHat,
      color: '#3b82f6',
    },
    {
      title: 'Pending',
      subtitle: 'Awaiting review',
      value: stats.pending,
      description: 'Features pending QA review',
      icon: Clock,
      color: '#f59e0b',
    },
    {
      title: 'Approved',
      subtitle: 'QA passed',
      value: stats.approved,
      description: 'Features approved after review',
      icon: CheckCircle,
      color: '#22c55e',
    },
    {
      title: 'Rejected',
      subtitle: 'QA failed',
      value: stats.rejected,
      description: 'Features rejected — need retake',
      icon: XCircle,
      color: '#ef4444',
    },
    {
      title: 'Rework',
      subtitle: 'Sent back',
      value: stats.rework_needed,
      description: 'Features sent back for rework',
      icon: AlertTriangle,
      color: '#f97316',
    },
    ...(stats.unidentified > 0 ? [{
      title: 'Unidentified',
      subtitle: 'Unknown features',
      value: stats.unidentified,
      description: 'Features with non-standard IDs (filenames, not pole numbers)',
      icon: AlertTriangle,
      color: '#6b7280',
    }] : []),
  ], [stats, filters.discipline]);

  const handleRowClick = (feature: FeatureRow) => {
    router.push(`/field-ops/${feature.id}`);
  };

  // Debounced search
  const searchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [searchInput, setSearchInput] = useState('');

  const updateFilter = (key: keyof Filters, value: string | number) => {
    if (key === 'search') {
      setSearchInput(value as string);
      if (searchTimerRef.current) clearTimeout(searchTimerRef.current);
      searchTimerRef.current = setTimeout(() => {
        setFilters(prev => ({ ...prev, search: value as string, page: 1 }));
      }, 300);
      return;
    }
    setFilters(prev => ({ ...prev, [key]: value, page: key === 'page' ? value as number : 1 }));
  };

  const statusBadge = (status: string) => {
    const colors: Record<string, string> = {
      pending: 'bg-yellow-500/20 text-yellow-400',
      in_review: 'bg-blue-500/20 text-blue-400',
      approved: 'bg-green-500/20 text-green-400',
      rejected: 'bg-red-500/20 text-red-400',
      rework_needed: 'bg-orange-500/20 text-orange-400',
      escalated: 'bg-purple-500/20 text-purple-400',
      unidentified: 'bg-gray-500/20 text-gray-400',
    };
    return (
      <span className={`px-2 py-0.5 rounded text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
        {status.replace('_', ' ')}
      </span>
    );
  };

  const confidenceBadge = (confidence: number | null) => {
    if (confidence === null) return <span className="text-gray-500 text-xs">—</span>;
    const pct = Math.round(confidence * 100);
    const color = pct >= 80 ? 'text-green-400' : pct >= 60 ? 'text-yellow-400' : 'text-red-400';
    return <span className={`text-xs font-mono font-medium ${color}`}>{pct}%</span>;
  };

  return (
    <div className="space-y-6">
      {/* Header — timestamp + refresh only (module header provided by ModulePage) */}
      <div className="flex items-center justify-end">
        <div className="flex items-center gap-3">
          {lastRefresh && (
            <span className="text-xs text-gray-500">
              Last updated: {lastRefresh.toLocaleTimeString()}
            </span>
          )}
          <button
            onClick={fetchData}
            disabled={loading}
            className="flex items-center gap-2 px-3 py-2 bg-[var(--card-bg)] border border-[var(--border-color)] rounded-lg text-sm text-gray-300 hover:bg-[var(--hover-bg)] transition-colors"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            Refresh
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <StatsGrid cards={statCards} columns={stats.unidentified > 0 ? 6 : 5} />

      {/* Discipline Tabs */}
      <div className="flex gap-1 bg-[var(--card-bg)] p-1 rounded-lg border border-[var(--border-color)]">
        {DISCIPLINE_TABS.map(tab => {
          const Icon = tab.icon;
          const isActive = filters.discipline === tab.key;
          return (
            <button
              key={tab.key}
              onClick={() => updateFilter('discipline', tab.key)}
              className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                isActive
                  ? 'bg-blue-600 text-white'
                  : 'text-gray-400 hover:text-white hover:bg-[var(--hover-bg)]'
              }`}
            >
              <Icon className="w-4 h-4" />
              {tab.label}
            </button>
          );
        })}
      </div>

      {/* Filter Bar */}
      <div className="flex flex-wrap items-center gap-3">
        {/* Project Selector */}
        <Select value={filters.projectId || '__all__'} onValueChange={v => updateFilter('projectId', v === '__all__' ? '' : v)}>
          <SelectTrigger className="w-[160px] h-9">
            <SelectValue placeholder="All Projects" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="__all__">All Projects</SelectItem>
            {projects.map(p => (
              <SelectItem key={p.id} value={p.id}>{p.name}</SelectItem>
            ))}
          </SelectContent>
        </Select>

        {/* Search */}
        <div className="relative flex-1 min-w-[200px] max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
          <input
            type="text"
            placeholder="Search by feature ID, pole number..."
            value={searchInput}
            onChange={e => updateFilter('search', e.target.value)}
            className="w-full pl-9 pr-3 py-2 bg-[var(--card-bg)] border border-[var(--border-color)] rounded-lg text-sm text-gray-300 placeholder-gray-500"
          />
        </div>

        {/* Status Filter */}
        <Select value={filters.workflowStatus || '__all__'} onValueChange={v => updateFilter('workflowStatus', v === '__all__' ? '' : v)}>
          <SelectTrigger className="w-[160px] h-9">
            <SelectValue placeholder="All Statuses" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="__all__">All Statuses</SelectItem>
            <SelectItem value="pending">Pending</SelectItem>
            <SelectItem value="in_review">In Review</SelectItem>
            <SelectItem value="approved">Approved</SelectItem>
            <SelectItem value="rejected">Rejected</SelectItem>
            <SelectItem value="rework_needed">Rework Needed</SelectItem>
            <SelectItem value="escalated">Escalated</SelectItem>
            <SelectItem value="unidentified">Unidentified</SelectItem>
          </SelectContent>
        </Select>

        {/* Priority Filter */}
        <Select value={filters.priority || '__all__'} onValueChange={v => updateFilter('priority', v === '__all__' ? '' : v)}>
          <SelectTrigger className="w-[160px] h-9">
            <SelectValue placeholder="All Priorities" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="__all__">All Priorities</SelectItem>
            <SelectItem value="urgent">Urgent</SelectItem>
            <SelectItem value="high">High</SelectItem>
            <SelectItem value="normal">Normal</SelectItem>
            <SelectItem value="low">Low</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Results Count */}
      <div className="text-sm text-gray-400">
        {totalCount} features total
        {totalPages > 1 && ` \u2022 Page ${filters.page} of ${totalPages}`}
      </div>

      {/* Data Grid */}
      <div className="bg-[var(--card-bg)] border border-[var(--border-color)] rounded-lg overflow-hidden">
        <table className="w-full">
          <thead>
            <tr className="border-b border-[var(--border-color)]">
              <th className="text-left px-4 py-3 text-xs font-medium text-gray-400 uppercase tracking-wider">Feature</th>
              <th className="text-left px-4 py-3 text-xs font-medium text-gray-400 uppercase tracking-wider">Zone</th>
              <th className="text-left px-4 py-3 text-xs font-medium text-gray-400 uppercase tracking-wider">PON</th>
              <th className="text-center px-4 py-3 text-xs font-medium text-gray-400 uppercase tracking-wider">Photos</th>
              <th className="text-center px-4 py-3 text-xs font-medium text-gray-400 uppercase tracking-wider">AI Score</th>
              <th className="text-center px-4 py-3 text-xs font-medium text-gray-400 uppercase tracking-wider">Status</th>
              <th className="text-center px-4 py-3 text-xs font-medium text-gray-400 uppercase tracking-wider">Decision</th>
              <th className="text-left px-4 py-3 text-xs font-medium text-gray-400 uppercase tracking-wider">Assigned</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[var(--border-color)]">
            {loading && features.length === 0 ? (
              <tr>
                <td colSpan={8} className="px-4 py-12 text-center text-gray-500">
                  <RefreshCw className="w-6 h-6 animate-spin mx-auto mb-2" />
                  Loading features...
                </td>
              </tr>
            ) : features.length === 0 ? (
              <tr>
                <td colSpan={8} className="px-4 py-12 text-center text-gray-500">
                  No features found. Select a project or adjust filters.
                </td>
              </tr>
            ) : (
              features.map(f => (
                <tr
                  key={f.id}
                  onClick={() => handleRowClick(f)}
                  className="cursor-pointer hover:bg-[var(--hover-bg)] transition-colors"
                >
                  <td className="px-4 py-3">
                    <div className="font-medium text-white text-sm">{f.feature_id}</div>
                    <div className="text-xs text-gray-500">{f.project_name}</div>
                  </td>
                  <td className="px-4 py-3 text-sm text-gray-300">
                    {f.zone_no !== null ? `Z${f.zone_no}` : '—'}
                  </td>
                  <td className="px-4 py-3 text-sm text-gray-300">
                    {f.pon_no !== null ? `P${f.pon_no}` : '—'}
                  </td>
                  <td className="px-4 py-3 text-center text-sm text-gray-300">
                    {f.photo_count}
                  </td>
                  <td className="px-4 py-3 text-center">
                    {confidenceBadge(f.vlm_confidence)}
                  </td>
                  <td className="px-4 py-3 text-center">
                    {statusBadge(f.workflow_status)}
                  </td>
                  <td className="px-4 py-3 text-center text-sm">
                    {f.qa_decision ? (
                      <span className={`font-medium ${
                        f.qa_decision === 'PASS' ? 'text-green-400' :
                        f.qa_decision === 'FAIL' ? 'text-red-400' : 'text-orange-400'
                      }`}>
                        {f.qa_decision}
                      </span>
                    ) : (
                      <span className="text-gray-500">—</span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-sm text-gray-400">
                    {f.assigned_to || '—'}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <button
            disabled={filters.page <= 1}
            onClick={() => updateFilter('page', filters.page - 1)}
            className="px-3 py-2 bg-[var(--card-bg)] border border-[var(--border-color)] rounded-lg text-sm text-gray-300 hover:bg-[var(--hover-bg)] disabled:opacity-50"
          >
            Previous
          </button>
          <span className="text-sm text-gray-400">
            Page {filters.page} of {totalPages}
          </span>
          <button
            disabled={filters.page >= totalPages}
            onClick={() => updateFilter('page', filters.page + 1)}
            className="px-3 py-2 bg-[var(--card-bg)] border border-[var(--border-color)] rounded-lg text-sm text-gray-300 hover:bg-[var(--hover-bg)] disabled:opacity-50"
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
}

/**
 * OTDR Testing Page
 *
 * Displays EXFO Exchange test results synced into FibreFlow.
 * Features: Stats cards, filters, results table, sync trigger.
 */

'use client';

import { useState, useEffect, useCallback } from 'react';
import {
  RefreshCw,
  CheckCircle,
  XCircle,
  Radio,
  Search,
  Cpu,
  Activity,
  Users,
  ChevronLeft,
  ChevronRight,
} from 'lucide-react';
import { StatsGrid } from '@/components/dashboard/EnhancedStatCard';
import type { EnhancedStatCardProps } from '@/components/dashboard/EnhancedStatCard';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { log } from '@/lib/logger';

// =============================================================================
// Types
// =============================================================================

interface TestResult {
  id: string;
  exfo_result_id: string;
  exfo_workspace_id: string;
  test_type: string;
  test_name: string;
  job_name: string | null;
  global_verdict: string | null;
  test_date_time: string | null;
  parsed_project: string | null;
  parsed_pole: string | null;
  parsed_cabinet: string | null;
  parsed_port: string | null;
  parsed_link: string | null;
  parsed_fiber: string | null;
  unit_a_serial: string | null;
  unit_a_model: string | null;
  unit_b_serial: string | null;
  unit_b_model: string | null;
  operator_a: string | null;
  cable_id: string | null;
  fiber_id: string | null;
  location_a: string | null;
  location_b: string | null;
  project_id: string | null;
  asset_id: string | null;
  attachments_count: number;
  project_name?: string;
  asset_name?: string;
}

interface Stats {
  total: number;
  passed: number;
  failed: number;
  pending: number;
  olts_count: number;
  iolm_count: number;
  unique_equipment: number;
  unique_operators: number;
}

interface ProjectOption {
  code: string;
  project_id: string | null;
  project_name: string | null;
  result_count: number;
}

// =============================================================================
// Component
// =============================================================================

export function OtdrTestingPage() {
  const [results, setResults] = useState<TestResult[]>([]);
  const [stats, setStats] = useState<Stats | null>(null);
  const [projects, setProjects] = useState<ProjectOption[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState(false);
  const [total, setTotal] = useState(0);

  // Filters
  const [projectFilter, setProjectFilter] = useState('');
  const [testTypeFilter, setTestTypeFilter] = useState('');
  const [verdictFilter, setVerdictFilter] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(1);
  const pageSize = 50;

  // Fetch results
  const fetchResults = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      params.append('page', String(page));
      params.append('pageSize', String(pageSize));
      if (projectFilter) params.append('projectId', projectFilter);
      if (testTypeFilter) params.append('testType', testTypeFilter);
      if (verdictFilter) params.append('verdict', verdictFilter);
      if (searchTerm) params.append('search', searchTerm);

      const res = await fetch(`/api/exfo/results?${params}`, { credentials: 'include' });
      const data = await res.json();

      if (data.success) {
        setResults(data.data.results || []);
        setTotal(data.data.total || 0);
      }
    } catch (err) {
      log.error('Failed to fetch EXFO results', { error: String(err) });
    } finally {
      setLoading(false);
    }
  }, [page, projectFilter, testTypeFilter, verdictFilter, searchTerm]);

  // Fetch stats
  const fetchStats = useCallback(async () => {
    try {
      const params = new URLSearchParams();
      params.append('action', 'stats');
      if (projectFilter) params.append('projectId', projectFilter);

      const res = await fetch(`/api/exfo/results?${params}`, { credentials: 'include' });
      const data = await res.json();

      if (data.success) {
        setStats(data.data);
      }
    } catch (err) {
      log.error('Failed to fetch EXFO stats', { error: String(err) });
    }
  }, [projectFilter]);

  // Fetch projects
  const fetchProjects = useCallback(async () => {
    try {
      const res = await fetch('/api/exfo/results?action=projects', { credentials: 'include' });
      const data = await res.json();
      if (data.success) {
        setProjects(data.data.projects || []);
      }
    } catch (err) {
      log.error('Failed to fetch EXFO projects', { error: String(err) });
    }
  }, []);

  useEffect(() => {
    fetchResults();
  }, [fetchResults]);

  useEffect(() => {
    fetchStats();
    fetchProjects();
  }, [fetchStats, fetchProjects]);

  // Trigger sync
  const handleSync = async () => {
    setSyncing(true);
    try {
      const res = await fetch('/api/exfo/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ fetchDetails: true }),
      });
      const data = await res.json();

      if (data.success) {
        log.info('EXFO sync completed', data.data);
        // Refresh data
        await Promise.all([fetchResults(), fetchStats(), fetchProjects()]);
      }
    } catch (err) {
      log.error('EXFO sync failed', { error: String(err) });
    } finally {
      setSyncing(false);
    }
  };

  // Stats cards
  const statCards: EnhancedStatCardProps[] = stats ? [
    {
      title: 'Total Tests',
      value: Number(stats.total),
      icon: Activity,
      color: 'blue' as const,
    },
    {
      title: 'Passed',
      value: Number(stats.passed),
      icon: CheckCircle,
      color: 'green' as const,
      subtitle: stats.total > 0 ? `${Math.round((Number(stats.passed) / Number(stats.total)) * 100)}%` : undefined,
    },
    {
      title: 'Failed',
      value: Number(stats.failed),
      icon: XCircle,
      color: 'red' as const,
      subtitle: stats.total > 0 ? `${Math.round((Number(stats.failed) / Number(stats.total)) * 100)}%` : undefined,
    },
    {
      title: 'Equipment',
      value: Number(stats.unique_equipment),
      icon: Cpu,
      color: 'purple' as const,
    },
    {
      title: 'OLTS Tests',
      value: Number(stats.olts_count),
      icon: Radio,
      color: 'cyan' as const,
    },
    {
      title: 'Operators',
      value: Number(stats.unique_operators),
      icon: Users,
      color: 'amber' as const,
    },
  ] : [];

  const totalPages = Math.ceil(total / pageSize);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-white">OTDR Testing</h1>
          <p className="text-sm text-gray-400 mt-1">
            Fiber optic test results from EXFO Exchange
          </p>
        </div>
        <button
          onClick={handleSync}
          disabled={syncing}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-lg text-sm font-medium transition-colors"
        >
          <RefreshCw className={`w-4 h-4 ${syncing ? 'animate-spin' : ''}`} />
          {syncing ? 'Syncing...' : 'Sync Now'}
        </button>
      </div>

      {/* Stats Grid */}
      {stats && <StatsGrid cards={statCards} columns={3} />}

      {/* Filters */}
      <div className="flex flex-wrap gap-3 items-center">
        <div className="relative flex-1 min-w-[200px] max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="Search tests, cables, operators..."
            value={searchTerm}
            onChange={(e) => { setSearchTerm(e.target.value); setPage(1); }}
            className="w-full pl-10 pr-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-white text-sm placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>

        <Select value={projectFilter} onValueChange={(v) => { setProjectFilter(v === 'all' ? '' : v); setPage(1); }}>
          <SelectTrigger className="w-[180px] bg-gray-800 border-gray-700">
            <SelectValue placeholder="All Projects" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Projects</SelectItem>
            {projects.filter(p => p.project_id).map((p) => (
              <SelectItem key={p.project_id!} value={p.project_id!}>
                {p.project_name || p.code} ({p.result_count})
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        <Select value={testTypeFilter} onValueChange={(v) => { setTestTypeFilter(v === 'all' ? '' : v); setPage(1); }}>
          <SelectTrigger className="w-[140px] bg-gray-800 border-gray-700">
            <SelectValue placeholder="All Types" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Types</SelectItem>
            <SelectItem value="olts">OLTS</SelectItem>
            <SelectItem value="iolm">iOLM</SelectItem>
          </SelectContent>
        </Select>

        <Select value={verdictFilter} onValueChange={(v) => { setVerdictFilter(v === 'all' ? '' : v); setPage(1); }}>
          <SelectTrigger className="w-[140px] bg-gray-800 border-gray-700">
            <SelectValue placeholder="All Results" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Results</SelectItem>
            <SelectItem value="Pass">Pass</SelectItem>
            <SelectItem value="Fail">Fail</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Results Table */}
      <div className="bg-gray-900 border border-gray-800 rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-800 bg-gray-900/50">
                <th className="text-left py-3 px-4 text-gray-400 font-medium">Test Name</th>
                <th className="text-left py-3 px-4 text-gray-400 font-medium">Type</th>
                <th className="text-left py-3 px-4 text-gray-400 font-medium">Result</th>
                <th className="text-left py-3 px-4 text-gray-400 font-medium">Date</th>
                <th className="text-left py-3 px-4 text-gray-400 font-medium">Pole</th>
                <th className="text-left py-3 px-4 text-gray-400 font-medium">Cable / Fiber</th>
                <th className="text-left py-3 px-4 text-gray-400 font-medium">Equipment</th>
                <th className="text-left py-3 px-4 text-gray-400 font-medium">Operator</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr>
                  <td colSpan={8} className="py-12 text-center text-gray-500">
                    <RefreshCw className="w-5 h-5 animate-spin mx-auto mb-2" />
                    Loading...
                  </td>
                </tr>
              ) : results.length === 0 ? (
                <tr>
                  <td colSpan={8} className="py-12 text-center text-gray-500">
                    {total === 0
                      ? 'No test results synced yet. Click "Sync Now" to import from EXFO Exchange.'
                      : 'No results match your filters.'}
                  </td>
                </tr>
              ) : (
                results.map((r) => (
                  <tr
                    key={r.id}
                    className="border-b border-gray-800/50 hover:bg-gray-800/30 transition-colors"
                  >
                    <td className="py-3 px-4">
                      <div className="text-white font-medium truncate max-w-[280px]" title={r.test_name}>
                        {r.test_name}
                      </div>
                      {r.job_name && (
                        <div className="text-gray-500 text-xs truncate max-w-[280px]">{r.job_name}</div>
                      )}
                    </td>
                    <td className="py-3 px-4">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${
                        r.test_type === 'olts'
                          ? 'bg-cyan-500/10 text-cyan-400'
                          : 'bg-purple-500/10 text-purple-400'
                      }`}>
                        {r.test_type.toUpperCase()}
                      </span>
                    </td>
                    <td className="py-3 px-4">
                      <VerdictBadge verdict={r.global_verdict} />
                    </td>
                    <td className="py-3 px-4 text-gray-300 whitespace-nowrap">
                      {r.test_date_time
                        ? new Date(r.test_date_time).toLocaleDateString('en-ZA')
                        : '—'}
                    </td>
                    <td className="py-3 px-4 text-gray-300">
                      {r.parsed_pole || '—'}
                    </td>
                    <td className="py-3 px-4 text-gray-300">
                      <div>{r.cable_id || r.parsed_link || '—'}</div>
                      {r.fiber_id && <div className="text-xs text-gray-500">{r.fiber_id}</div>}
                    </td>
                    <td className="py-3 px-4">
                      <div className="text-gray-300 text-xs">
                        {r.unit_a_serial || '—'}
                      </div>
                      {r.unit_a_model && (
                        <div className="text-gray-500 text-xs truncate max-w-[140px]">{r.unit_a_model}</div>
                      )}
                      {r.asset_name && (
                        <div className="text-blue-400 text-xs">{r.asset_name}</div>
                      )}
                    </td>
                    <td className="py-3 px-4 text-gray-300 text-xs">
                      {r.operator_a || '—'}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="flex items-center justify-between px-4 py-3 border-t border-gray-800">
            <span className="text-sm text-gray-400">
              {((page - 1) * pageSize) + 1}–{Math.min(page * pageSize, total)} of {total}
            </span>
            <div className="flex items-center gap-2">
              <button
                onClick={() => setPage(p => Math.max(1, p - 1))}
                disabled={page <= 1}
                className="p-1.5 rounded hover:bg-gray-800 disabled:opacity-30 text-gray-400"
              >
                <ChevronLeft className="w-4 h-4" />
              </button>
              <span className="text-sm text-gray-400">
                {page} / {totalPages}
              </span>
              <button
                onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                disabled={page >= totalPages}
                className="p-1.5 rounded hover:bg-gray-800 disabled:opacity-30 text-gray-400"
              >
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// =============================================================================
// Verdict Badge
// =============================================================================

function VerdictBadge({ verdict }: { verdict: string | null }) {
  if (verdict === 'Pass') {
    return (
      <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium bg-green-500/10 text-green-400">
        <CheckCircle className="w-3 h-3" /> Pass
      </span>
    );
  }
  if (verdict === 'Fail') {
    return (
      <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium bg-red-500/10 text-red-400">
        <XCircle className="w-3 h-3" /> Fail
      </span>
    );
  }
  return (
    <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-500/10 text-gray-400">
      —
    </span>
  );
}

/**
 * ReviewWizard — 5-Phase QA Wizard for Construction Reviews
 *
 * Phases:
 *   1. Prerequisites — verify photos exist, feature data loaded
 *   2. Photo Review — checklist walkthrough with VLM scores
 *   3. Data Validation — verify VLM-extracted data matches QField
 *   4. Final Decision — PASS / FAIL / REWORK_NEEDED
 *   5. Feedback — WhatsApp notification to technician
 *
 * Pattern: Follows Activate QA Centre wizard conventions
 */

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import {
  ArrowLeft,
  ArrowRight,
  CheckCircle,
  XCircle,
  AlertTriangle,
  Loader2,
  Camera,
  ClipboardCheck,
  Database,
  Gavel,
  MessageSquare,
  Pencil,
  Check,
  X,
} from 'lucide-react';
import { log } from '@/lib/logger';
import { getChecklist } from '../../types/construction.types';
import type {
  Discipline,
  WorkflowStatus,
  QaDecision,
  QaReasonCode,
  ChecklistStep,
} from '../../types';
import { PhasePrerequisites } from './PhasePrerequisites';
import { PhasePhotoReview } from './PhasePhotoReview';
import { PhaseDataValidation } from './PhaseDataValidation';
import { PhaseFinalDecision } from './PhaseFinalDecision';
import { PhaseFeedback } from './PhaseFeedback';

interface ReviewData {
  id: string;
  feature_id: string;
  feature_type: string;
  discipline: Discipline;
  project_name: string;
  zone_no: number | null;
  pon_no: number | null;
  photo_count: number;
  vlm_status: string;
  vlm_confidence: number | null;
  workflow_status: WorkflowStatus;
  qa_decision: QaDecision | null;
  qa_decision_at: string | null;
  qa_decision_by: string | null;
  qa_notes: string | null;
  qa_reason_code: string | null;
  wa_feedback_sent_at: string | null;
  wa_feedback_message: string | null;
  priority: string;
  assigned_to: string | null;
  [key: string]: unknown;
}

interface PhotoData {
  id: string;
  storage_key: string;
  source: string;
  filename: string | null;
  checklist_step: number | null;
  vlm_valid: boolean | null;
  vlm_confidence: number | null;
  vlm_issues: string[];
  vlm_feedback: string | null;
  manual_status: string | null;
  needs_retake: boolean;
  [key: string]: unknown;
}

type Phase = 'prerequisites' | 'photo_review' | 'data_validation' | 'final_decision' | 'feedback';

const PHASES: { key: Phase; label: string; icon: typeof CheckCircle }[] = [
  { key: 'prerequisites', label: 'Prerequisites', icon: ClipboardCheck },
  { key: 'photo_review', label: 'Photo Review', icon: Camera },
  { key: 'data_validation', label: 'Data Validation', icon: Database },
  { key: 'final_decision', label: 'Decision', icon: Gavel },
  { key: 'feedback', label: 'Feedback', icon: MessageSquare },
];

interface ReviewWizardProps {
  reviewId: string;
}

export function ReviewWizard({ reviewId }: ReviewWizardProps) {
  const router = useRouter();
  const [phase, setPhase] = useState<Phase>('prerequisites');
  const [review, setReview] = useState<ReviewData | null>(null);
  const [photos, setPhotos] = useState<PhotoData[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  // Checklist state (discipline-specific)
  const [checkedSteps, setCheckedSteps] = useState<Record<string, boolean>>({});
  const [extractedOverrides, setExtractedOverrides] = useState<Record<string, string>>({});
  const [decision, setDecision] = useState<QaDecision | null>(null);
  const [reasonCodes, setReasonCodes] = useState<QaReasonCode[]>([]);
  const [notes, setNotes] = useState('');

  // Feature rename state
  const [isEditingFeatureId, setIsEditingFeatureId] = useState(false);
  const [editFeatureId, setEditFeatureId] = useState('');

  // Fetch review data
  const fetchReview = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`/api/construction-qa/review?id=${reviewId}`, {
        credentials: 'include',
      });
      if (!res.ok) throw new Error(res.status === 404 ? 'Review not found' : `Failed to load review (${res.status})`);
      const data = await res.json();

      const rv = data.data?.review;
      if (!rv) {
        setError('Review not found');
        return;
      }

      setReview(rv);
      setPhotos(data.data?.photos || []);

      // Initialize checked steps from review data
      const checklist = getChecklist(rv.discipline);
      const initial: Record<string, boolean> = {};
      for (const step of checklist) {
        const col = getStepColumn(rv.discipline, step.step);
        initial[col] = Boolean(rv[col]);
      }
      setCheckedSteps(initial);

      // Restore decision if already made
      if (rv.qa_decision) {
        setDecision(rv.qa_decision);
        setNotes(rv.qa_notes || '');
      }

      // If already decided, jump to feedback phase
      if (rv.workflow_status === 'approved' || rv.workflow_status === 'rejected') {
        setPhase('feedback');
      }
    } catch (err) {
      setError((err as Error).message);
      log.error('Failed to load review', { module: 'construction-qa', error: (err as Error).message }, 'construction-qa');
    } finally {
      setLoading(false);
    }
  }, [reviewId]);

  useEffect(() => { fetchReview(); }, [fetchReview]);

  // Save checklist progress
  const saveProgress = async () => {
    if (!review) return;
    setSaving(true);
    try {
      await fetch('/api/construction-qa/review', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          reviewId: review.id,
          stepUpdates: checkedSteps,
          extractedDataUpdates: extractedOverrides,
          notes,
          reviewedBy: 'current_user', // TODO: get from auth context
        }),
      });
    } catch (err) {
      log.error('Failed to save progress', { module: 'construction-qa', error: (err as Error).message }, 'construction-qa');
    } finally {
      setSaving(false);
    }
  };

  // Submit final decision
  const submitDecision = async () => {
    if (!review || !decision) return;
    setSaving(true);
    try {
      const res = await fetch('/api/construction-qa/final-decision', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          reviewId: review.id,
          decision,
          reasonCodes,
          notes,
          sendFeedback: decision !== 'PASS',
          decidedBy: 'current_user',
        }),
      });

      if (res.ok) {
        await fetchReview();
        setPhase('feedback');
      }
    } catch (err) {
      log.error('Failed to submit decision', { module: 'construction-qa', error: (err as Error).message }, 'construction-qa');
    } finally {
      setSaving(false);
    }
  };

  // Save feature ID rename
  const saveFeatureId = async () => {
    if (!review || !editFeatureId.trim() || editFeatureId.trim() === review.feature_id) {
      setIsEditingFeatureId(false);
      return;
    }
    setSaving(true);
    try {
      const res = await fetch('/api/construction-qa/review', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          reviewId: review.id,
          featureIdUpdate: editFeatureId.trim(),
          reviewedBy: 'current_user',
        }),
      });
      if (res.ok) {
        await fetchReview();
        setIsEditingFeatureId(false);
      }
    } catch (err) {
      log.error('Failed to update feature ID', { module: 'construction-qa', error: (err as Error).message }, 'construction-qa');
    } finally {
      setSaving(false);
    }
  };

  const goNext = async () => {
    const idx = PHASES.findIndex(p => p.key === phase);
    if (idx < PHASES.length - 1) {
      await saveProgress();
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      setPhase(PHASES[idx + 1]!.key);
    }
  };

  const goPrev = () => {
    const idx = PHASES.findIndex(p => p.key === phase);
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    if (idx > 0) setPhase(PHASES[idx - 1]!.key);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-24">
        <Loader2 className="w-8 h-8 animate-spin text-blue-500" />
      </div>
    );
  }

  if (error || !review) {
    return (
      <div className="text-center py-24">
        <XCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
        <h2 className="text-xl font-bold text-white mb-2">Review Not Found</h2>
        <p className="text-gray-400 mb-6">{error || 'This review does not exist.'}</p>
        <button
          onClick={() => router.push('/field-ops')}
          className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
        >
          Back to QA Centre
        </button>
      </div>
    );
  }

  const checklist = getChecklist(review.discipline);
  const phaseIdx = PHASES.findIndex(p => p.key === phase);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <button
          onClick={() => router.push('/field-ops')}
          className="p-2 hover:bg-[var(--hover-bg)] rounded-lg transition-colors"
        >
          <ArrowLeft className="w-5 h-5 text-gray-400" />
        </button>
        <div className="flex-1">
          <div className="flex items-center gap-2">
            {isEditingFeatureId ? (
              <div className="flex items-center gap-2">
                <input
                  type="text"
                  value={editFeatureId}
                  onChange={e => setEditFeatureId(e.target.value)}
                  onKeyDown={e => {
                    if (e.key === 'Enter') saveFeatureId();
                    if (e.key === 'Escape') setIsEditingFeatureId(false);
                  }}
                  className="px-2 py-1 bg-gray-800 border border-blue-500 rounded text-white text-lg font-bold focus:outline-none focus:ring-2 focus:ring-blue-500/50"
                  autoFocus
                />
                <button onClick={saveFeatureId} disabled={saving} className="p-1 text-green-400 hover:text-green-300" title="Save">
                  <Check className="w-5 h-5" />
                </button>
                <button onClick={() => setIsEditingFeatureId(false)} className="p-1 text-gray-400 hover:text-gray-300" title="Cancel">
                  <X className="w-5 h-5" />
                </button>
              </div>
            ) : (
              <>
                <h1 className="text-xl font-bold text-white">{review.feature_id}</h1>
                <button
                  onClick={() => { setEditFeatureId(review.feature_id); setIsEditingFeatureId(true); }}
                  className="p-1 text-gray-500 hover:text-gray-300 transition-colors"
                  title="Rename or reassign to another pole"
                >
                  <Pencil className="w-4 h-4" />
                </button>
              </>
            )}
          </div>
          <p className="text-sm text-gray-400">
            {review.project_name} · {review.discipline} ·{' '}
            {review.zone_no !== null ? `Z${review.zone_no}` : ''}{' '}
            {review.pon_no !== null ? `P${review.pon_no}` : ''}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <span className={`px-3 py-1 rounded-full text-xs font-medium ${
            review.workflow_status === 'approved' ? 'bg-green-500/20 text-green-400' :
            review.workflow_status === 'rejected' ? 'bg-red-500/20 text-red-400' :
            review.workflow_status === 'rework_needed' ? 'bg-orange-500/20 text-orange-400' :
            'bg-yellow-500/20 text-yellow-400'
          }`}>
            {review.workflow_status.replace('_', ' ')}
          </span>
          <span className="text-sm text-gray-500">{photos.length} photos</span>
        </div>
      </div>

      {/* Phase Progress Bar */}
      <div className="flex items-center gap-1 bg-[var(--card-bg)] p-2 rounded-lg border border-[var(--border-color)]">
        {PHASES.map((p, i) => {
          const Icon = p.icon;
          const isActive = p.key === phase;
          const isDone = i < phaseIdx;
          return (
            <button
              key={p.key}
              onClick={() => setPhase(p.key)}
              className={`flex items-center gap-2 px-3 py-2 rounded-md text-sm font-medium transition-colors flex-1 justify-center ${
                isActive
                  ? 'bg-blue-600 text-white'
                  : isDone
                    ? 'bg-green-600/20 text-green-400'
                    : 'text-gray-500 hover:text-gray-300 hover:bg-[var(--hover-bg)]'
              }`}
            >
              {isDone ? <CheckCircle className="w-4 h-4" /> : <Icon className="w-4 h-4" />}
              <span className="hidden md:inline">{p.label}</span>
            </button>
          );
        })}
      </div>

      {/* Phase Content */}
      <div className="bg-[var(--card-bg)] border border-[var(--border-color)] rounded-lg p-6 min-h-[400px]">
        {phase === 'prerequisites' && (
          <PhasePrerequisites
            review={review}
            photos={photos}
            checklist={checklist}
          />
        )}
        {phase === 'photo_review' && (
          <PhasePhotoReview
            review={review}
            photos={photos}
            checklist={checklist}
            checkedSteps={checkedSteps}
            onStepChange={(col, val) => setCheckedSteps(prev => ({ ...prev, [col]: val }))}
          />
        )}
        {phase === 'data_validation' && (
          <PhaseDataValidation
            review={review}
            overrides={extractedOverrides}
            onOverride={(field, val) => setExtractedOverrides(prev => ({ ...prev, [field]: val }))}
          />
        )}
        {phase === 'final_decision' && (
          <PhaseFinalDecision
            review={review}
            checklist={checklist}
            checkedSteps={checkedSteps}
            decision={decision}
            reasonCodes={reasonCodes}
            notes={notes}
            onDecisionChange={setDecision}
            onReasonCodesChange={setReasonCodes}
            onNotesChange={setNotes}
          />
        )}
        {phase === 'feedback' && (
          <PhaseFeedback review={review} />
        )}
      </div>

      {/* Navigation Buttons — pr-20 clears the Velo chatbot FAB */}
      <div className="flex items-center justify-between pr-20">
        <button
          onClick={goPrev}
          disabled={phaseIdx === 0}
          className="flex items-center gap-2 px-4 py-2 bg-[var(--card-bg)] border border-[var(--border-color)] rounded-lg text-sm text-gray-300 hover:bg-[var(--hover-bg)] disabled:opacity-50"
        >
          <ArrowLeft className="w-4 h-4" />
          Previous
        </button>

        <div className="flex items-center gap-3">
          {saving && <Loader2 className="w-4 h-4 animate-spin text-blue-400" />}

          {phase === 'final_decision' && decision ? (
            <button
              onClick={submitDecision}
              disabled={saving}
              className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-medium text-white ${
                decision === 'PASS' ? 'bg-green-600 hover:bg-green-700' :
                decision === 'FAIL' ? 'bg-red-600 hover:bg-red-700' :
                'bg-orange-600 hover:bg-orange-700'
              } disabled:opacity-50`}
            >
              <Gavel className="w-4 h-4" />
              Submit {decision}
            </button>
          ) : phase !== 'feedback' ? (
            <button
              onClick={goNext}
              disabled={saving || phaseIdx >= PHASES.length - 1}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm hover:bg-blue-700 disabled:opacity-50"
            >
              Next
              <ArrowRight className="w-4 h-4" />
            </button>
          ) : null}
        </div>
      </div>
    </div>
  );
}

/** Get the database column name for a discipline step */
function getStepColumn(discipline: Discipline, step: number): string {
  const pad = String(step).padStart(2, '0');
  const stepNames: Record<string, Record<number, string>> = {
    civil: {
      1: 'before_photo', 2: 'during_photo', 3: 'depth_photo', 4: 'end_plates',
      5: 'compaction', 6: 'level_check', 7: 'after_photo', 8: 'signature',
    },
    optical: {
      1: 'cable_route', 2: 'attachment', 3: 'slack_coil',
      4: 'cable_label', 5: 'no_backfeed', 6: 'sag_ok',
    },
    splicing: {
      1: 'dome_on_pole', 2: 'dome_label', 3: 'open_dome', 4: 'splice_protectors',
      5: 'slack_management', 6: 'strength_members', 7: 'seals_dustcaps', 8: 'pole_id',
      11: 'cable_entries', 12: 'strength_members', 13: 'tube_routing',
      14: 'tray_entries', 15: 'coiling_protectors', 16: 'readable_labels',
    },
  };
  return `${discipline}_step_${pad}_${stepNames[discipline]?.[step] || 'unknown'}`;
}

/**
 * POST /api/construction-qa/ingest-qfield
 *
 * Triggers ingestion of QField photos into the Construction QA system.
 * Reads from qfield_photo_validations and creates review + photo records.
 *
 * Auth: session cookie OR x-cron-secret header (for cron jobs)
 *
 * Body: { projectId?, discipline?, sinceDate?, dryRun? }
 *   - projectId: FibreFlow project UUID (optional — omit to ingest ALL mapped projects)
 *   - discipline: 'civil' | 'optical' | 'splicing' | 'all' (default: 'all')
 *   - sinceDate: ISO date string to filter photos (optional)
 *   - dryRun: boolean (default: false)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { ingestQFieldPhotos, ingestAllQFieldPhotos } from '@/modules/construction-qa/services/qfieldIngestionService';

const CRON_SECRET = process.env.CRON_SECRET || '';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['POST']);
  }

  // Auth: cron secret or session cookie
  const cronSecret = req.headers['x-cron-secret'] || req.query.secret;
  if (cronSecret !== CRON_SECRET && !req.headers.cookie) {
    return apiResponse.unauthorized(res, 'Invalid cron secret');
  }

  try {
    const { projectId, discipline, sinceDate, dryRun } = req.body;

    if (!projectId) {
      // Ingest all mapped projects
      const result = await ingestAllQFieldPhotos({
        discipline: discipline || 'all',
        dryRun: Boolean(dryRun),
      });
      return apiResponse.success(res, { mode: 'all', dryRun: Boolean(dryRun), ...result });
    }

    const result = await ingestQFieldPhotos({
      projectId,
      discipline: discipline || 'all',
      sinceDate,
      dryRun: Boolean(dryRun),
    });

    return apiResponse.success(res, { mode: 'single', dryRun: Boolean(dryRun), ...result });
  } catch (error) {
    log.error('Ingest API error', { module: 'construction-qa', error: (error as Error).message });
    return apiResponse.internalError(res, error);
  }
}

export default handler;

/**
 * GET /api/qfield/qa-hierarchy
 * Returns project -> zone -> PON -> feature type hierarchy with photo counts
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth } from '@/lib/auth';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

interface HierarchyRow {
  zone_no: number | null;
  pon_no: number | null;
  work_type: string | null;
  photo_count: string;
  pending: string;
  approved: string;
  rejected: string;
}

interface FeatureRow {
  zone_no: number | null;
  pon_no: number | null;
  feature_id: string;
  work_type: string | null;
  photo_count: string;
  pending: string;
  approved: string;
  rejected: string;
}

async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['GET']);
  }

  try {
    const { projectId } = req.query;

    if (!projectId || typeof projectId !== 'string') {
      return apiResponse.badRequest(res, 'projectId is required');
    }

    // Get hierarchy grouped by zone, PON, and work type
    // Join to drops for zone_no/pon_no (drops table has the zone/PON data, poles table doesn't)
    // Use a subquery to get one zone/pon per pole_number to avoid inflated counts from multiple drops
    const rows: HierarchyRow[] = await sql`
      SELECT
        dz.zone_no,
        dz.pon_no,
        v.work_type,
        COUNT(*)::int as photo_count,
        COUNT(*) FILTER (WHERE v.workflow_status = 'pending')::int as pending,
        COUNT(*) FILTER (WHERE v.workflow_status = 'approved')::int as approved,
        COUNT(*) FILTER (WHERE v.workflow_status = 'rejected')::int as rejected
      FROM qfield_photo_validations v
      LEFT JOIN (
        SELECT pole_number AS feature_label, zone_no, pon_no FROM poles
        UNION ALL
        SELECT joint_label AS feature_label, zone_no, pon_no FROM joints
        UNION ALL
        SELECT * FROM (
          SELECT DISTINCT ON (pole_number) pole_number AS feature_label, zone_no, pon_no
          FROM drops ORDER BY pole_number, zone_no, pon_no
        ) d
      ) dz ON v.feature_id = dz.feature_label
      WHERE v.project_id = (
        SELECT id FROM qfield_projects WHERE id = ${projectId}::uuid
      )
      GROUP BY dz.zone_no, dz.pon_no, v.work_type
      ORDER BY dz.zone_no NULLS LAST, dz.pon_no NULLS LAST, v.work_type
    `;

    // Get individual features (poles/joints) per zone/PON
    const featureRows: FeatureRow[] = await sql`
      SELECT
        dz.zone_no,
        dz.pon_no,
        v.feature_id,
        v.work_type,
        COUNT(*)::int as photo_count,
        COUNT(*) FILTER (WHERE v.workflow_status = 'pending')::int as pending,
        COUNT(*) FILTER (WHERE v.workflow_status = 'approved')::int as approved,
        COUNT(*) FILTER (WHERE v.workflow_status = 'rejected')::int as rejected
      FROM qfield_photo_validations v
      LEFT JOIN (
        SELECT pole_number AS feature_label, zone_no, pon_no FROM poles
        UNION ALL
        SELECT joint_label AS feature_label, zone_no, pon_no FROM joints
        UNION ALL
        SELECT * FROM (
          SELECT DISTINCT ON (pole_number) pole_number AS feature_label, zone_no, pon_no
          FROM drops ORDER BY pole_number, zone_no, pon_no
        ) d
      ) dz ON v.feature_id = dz.feature_label
      WHERE v.project_id = (
        SELECT id FROM qfield_projects WHERE id = ${projectId}::uuid
      )
      AND v.feature_id IS NOT NULL
      GROUP BY dz.zone_no, dz.pon_no, v.feature_id, v.work_type
      ORDER BY dz.zone_no NULLS LAST, dz.pon_no NULLS LAST, v.feature_id
    `;

    // Index features by zone_no + pon_no key
    const featuresByPon = new Map<string, Array<{
      feature_id: string;
      work_type: string;
      photo_count: number;
      pending: number;
      approved: number;
      rejected: number;
    }>>();

    for (const fr of featureRows) {
      const key = `${fr.zone_no}_${fr.pon_no}`;
      if (!featuresByPon.has(key)) {
        featuresByPon.set(key, []);
      }
      featuresByPon.get(key)!.push({
        feature_id: fr.feature_id,
        work_type: fr.work_type || 'unknown',
        photo_count: Number(fr.photo_count),
        pending: Number(fr.pending),
        approved: Number(fr.approved),
        rejected: Number(fr.rejected),
      });
    }

    // Build the hierarchical structure
    const zoneMap = new Map<number | null, {
      zone_no: number | null;
      photo_count: number;
      pending: number;
      approved: number;
      rejected: number;
      ponMap: Map<number | null, {
        pon_no: number | null;
        photo_count: number;
        pending: number;
        approved: number;
        rejected: number;
        feature_types: Array<{
          work_type: string;
          photo_count: number;
          pending: number;
          approved: number;
          rejected: number;
        }>;
        features: Array<{
          feature_id: string;
          work_type: string;
          photo_count: number;
          pending: number;
          approved: number;
          rejected: number;
        }>;
      }>;
    }>();

    let totalPhotos = 0;
    let totalPending = 0;
    let totalApproved = 0;
    let totalRejected = 0;

    for (const row of rows) {
      const photoCount = Number(row.photo_count);
      const pending = Number(row.pending);
      const approved = Number(row.approved);
      const rejected = Number(row.rejected);

      totalPhotos += photoCount;
      totalPending += pending;
      totalApproved += approved;
      totalRejected += rejected;

      // Get or create zone
      if (!zoneMap.has(row.zone_no)) {
        zoneMap.set(row.zone_no, {
          zone_no: row.zone_no,
          photo_count: 0,
          pending: 0,
          approved: 0,
          rejected: 0,
          ponMap: new Map(),
        });
      }
      const zone = zoneMap.get(row.zone_no)!;
      zone.photo_count += photoCount;
      zone.pending += pending;
      zone.approved += approved;
      zone.rejected += rejected;

      // Get or create PON within zone
      if (!zone.ponMap.has(row.pon_no)) {
        zone.ponMap.set(row.pon_no, {
          pon_no: row.pon_no,
          photo_count: 0,
          pending: 0,
          approved: 0,
          rejected: 0,
          feature_types: [],
          features: [],
        });
      }
      const pon = zone.ponMap.get(row.pon_no)!;
      pon.photo_count += photoCount;
      pon.pending += pending;
      pon.approved += approved;
      pon.rejected += rejected;

      // Add feature type
      pon.feature_types.push({
        work_type: row.work_type || 'unknown',
        photo_count: photoCount,
        pending,
        approved,
        rejected,
      });
    }

    // Convert maps to arrays
    const zones = Array.from(zoneMap.values()).map(zone => ({
      zone_no: zone.zone_no,
      photo_count: zone.photo_count,
      pending: zone.pending,
      approved: zone.approved,
      rejected: zone.rejected,
      pons: Array.from(zone.ponMap.values()).map(pon => {
        const ponKey = `${zone.zone_no}_${pon.pon_no}`;
        return {
          pon_no: pon.pon_no,
          photo_count: pon.photo_count,
          pending: pon.pending,
          approved: pon.approved,
          rejected: pon.rejected,
          feature_types: pon.feature_types,
          features: featuresByPon.get(ponKey) || [],
        };
      }),
    }));

    return apiResponse.success(res, {
      zones,
      totals: {
        photo_count: totalPhotos,
        pending: totalPending,
        approved: totalApproved,
        rejected: totalRejected,
      },
    });
  } catch (error) {
    log.error('qfield-qa-hierarchy', error instanceof Error ? { message: error.message } : { error }, 'Fetch failed');
    return apiResponse.databaseError(res, error);
  }
}

export default withAuth(handler);

/**
 * GET /api/qfield/qa-stats
 * Dashboard statistics for QField QA
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, AuthenticatedRequest } from '@/lib/auth';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['GET']);
  }

  try {
    const authReq = req as AuthenticatedRequest;
    const currentUser = authReq.user?.email || authReq.user?.username;
    const { projectId } = req.query;

    // Get overall counts by workflow status
    const statusCounts = await sql`
      SELECT
        workflow_status,
        COUNT(*) as count
      FROM qfield_photo_validations
      WHERE 1=1 ${projectId ? sql`AND project_id = ${projectId}::uuid` : sql``}
      GROUP BY workflow_status
    `;

    // Get counts by AI result
    const aiCounts = await sql`
      SELECT
        CASE
          WHEN vlm_confidence IS NULL THEN 'not_validated'
          WHEN vlm_confidence >= 0.8 THEN 'high_confidence'
          WHEN vlm_confidence >= 0.6 THEN 'medium_confidence'
          ELSE 'low_confidence'
        END as confidence_level,
        COUNT(*) as count
      FROM qfield_photo_validations
      WHERE 1=1 ${projectId ? sql`AND project_id = ${projectId}::uuid` : sql``}
      GROUP BY confidence_level
    `;

    // Get needs retake count
    const retakeCounts = await sql`
      SELECT
        COUNT(*) FILTER (WHERE needs_retake = TRUE AND retake_completed_at IS NULL) as needs_retake,
        COUNT(*) FILTER (WHERE needs_retake = TRUE AND retake_completed_at IS NOT NULL) as retaken
      FROM qfield_photo_validations
      WHERE 1=1 ${projectId ? sql`AND project_id = ${projectId}::uuid` : sql``}
    `;

    // Get escalated count
    const escalatedCount = await sql`
      SELECT COUNT(*) as count
      FROM qfield_photo_validations
      WHERE escalation_level > 0
        AND workflow_status = 'escalated'
        ${projectId ? sql`AND project_id = ${projectId}::uuid` : sql``}
    `;

    // Get overdue count (past due date, not completed)
    const overdueCount = await sql`
      SELECT COUNT(*) as count
      FROM qfield_photo_validations
      WHERE due_date < NOW()
        AND workflow_status IN ('pending', 'in_review')
        ${projectId ? sql`AND project_id = ${projectId}::uuid` : sql``}
    `;

    // Get my queue count if user is logged in
    let myQueueCount = 0;
    if (currentUser) {
      const myQueue = await sql`
        SELECT COUNT(*) as count
        FROM qfield_photo_validations
        WHERE assigned_to = ${currentUser}
          AND workflow_status IN ('pending', 'in_review')
          ${projectId ? sql`AND project_id = ${projectId}::uuid` : sql``}
      `;
      myQueueCount = parseInt(myQueue[0]?.count || '0', 10);
    }

    // Get counts by work type
    const workTypeCounts = await sql`
      SELECT
        COALESCE(work_type, 'unknown') as work_type,
        COUNT(*) as total,
        COUNT(*) FILTER (WHERE workflow_status = 'approved') as approved,
        COUNT(*) FILTER (WHERE workflow_status = 'rejected') as rejected,
        COUNT(*) FILTER (WHERE workflow_status = 'pending') as pending,
        AVG(vlm_confidence) FILTER (WHERE vlm_confidence IS NOT NULL) as avg_confidence
      FROM qfield_photo_validations
      WHERE 1=1 ${projectId ? sql`AND project_id = ${projectId}::uuid` : sql``}
      GROUP BY work_type
      ORDER BY total DESC
    `;

    // Get counts by priority
    const priorityCounts = await sql`
      SELECT
        COALESCE(priority, 'normal') as priority,
        COUNT(*) as count
      FROM qfield_photo_validations
      WHERE workflow_status IN ('pending', 'in_review')
        ${projectId ? sql`AND project_id = ${projectId}::uuid` : sql``}
      GROUP BY priority
    `;

    // Get recent activity
    const recentActivity = await sql`
      SELECT
        action_type,
        action_by,
        action_at,
        notes
      FROM qfield_qa_actions
      ORDER BY action_at DESC
      LIMIT 10
    `;

    // Build response
    const stats = {
      summary: {
        total: statusCounts.reduce((sum, s) => sum + parseInt(s.count, 10), 0),
        pending: parseInt(statusCounts.find(s => s.workflow_status === 'pending')?.count || '0', 10),
        in_review: parseInt(statusCounts.find(s => s.workflow_status === 'in_review')?.count || '0', 10),
        approved: parseInt(statusCounts.find(s => s.workflow_status === 'approved')?.count || '0', 10),
        rejected: parseInt(statusCounts.find(s => s.workflow_status === 'rejected')?.count || '0', 10),
        escalated: parseInt(escalatedCount[0]?.count || '0', 10),
        overdue: parseInt(overdueCount[0]?.count || '0', 10),
        needs_retake: parseInt(retakeCounts[0]?.needs_retake || '0', 10),
        my_queue: myQueueCount,
      },
      ai_confidence: {
        not_validated: parseInt(aiCounts.find(c => c.confidence_level === 'not_validated')?.count || '0', 10),
        high_confidence: parseInt(aiCounts.find(c => c.confidence_level === 'high_confidence')?.count || '0', 10),
        medium_confidence: parseInt(aiCounts.find(c => c.confidence_level === 'medium_confidence')?.count || '0', 10),
        low_confidence: parseInt(aiCounts.find(c => c.confidence_level === 'low_confidence')?.count || '0', 10),
      },
      by_work_type: workTypeCounts.map(wt => ({
        work_type: wt.work_type,
        total: parseInt(wt.total, 10),
        approved: parseInt(wt.approved, 10),
        rejected: parseInt(wt.rejected, 10),
        pending: parseInt(wt.pending, 10),
        avg_confidence: wt.avg_confidence ? parseFloat(wt.avg_confidence).toFixed(2) : null,
      })),
      by_priority: {
        low: parseInt(priorityCounts.find(p => p.priority === 'low')?.count || '0', 10),
        normal: parseInt(priorityCounts.find(p => p.priority === 'normal')?.count || '0', 10),
        high: parseInt(priorityCounts.find(p => p.priority === 'high')?.count || '0', 10),
        urgent: parseInt(priorityCounts.find(p => p.priority === 'urgent')?.count || '0', 10),
      },
      recent_activity: recentActivity,
    };

    return apiResponse.success(res, stats);
  } catch (error) {
    log.error('qfield-qa-stats', error instanceof Error ? { message: error.message } : { error }, 'Stats fetch failed');
    return apiResponse.databaseError(res, error);
  }
}

