/**
 * API Route: /api/projects/[projectId]/pon-stages
 *
 * Returns PON stage tracker data: per-PON build pipeline progress
 * grouped by zone with 6 stages per PON.
 *
 * Method: GET
 * Query: ?zone=N (optional filter)
 *
 * Response: PonStagesResponse
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import pool from '@/lib/db';
import { log } from '@/lib/logger';
import { withAuth } from '@/lib/auth';
import type {
  PonStagesResponse,
  PonStageRow,
  PonStageData,
  ZoneStageNode,
  BuildStage,
  OverallStage,
} from '@/types/pon-stages.types';
import { BUILD_STAGES } from '@/types/pon-stages.types';

interface RawRow {
  zone_no: number;
  pon_no: number;
  permissions_total: string;
  permissions_approved: string;
  permissions_first_date: string | null;
  permissions_last_date: string | null;
  poles_total: string;
  poles_planted: string;
  poles_first_date: string | null;
  poles_last_date: string | null;
  cwc_total: string;
  cwc_complete: string;
  cwc_first_date: string | null;
  cwc_last_date: string | null;
  optical_total: string;
  optical_complete: string;
  optical_first_date: string | null;
  optical_last_date: string | null;
  atp_total: string;
  atp_passed: string;
  atp_first_date: string | null;
  atp_last_date: string | null;
  activation_total: string;
  activation_complete: string;
  activation_first_date: string | null;
  activation_last_date: string | null;
  overall_stage: string;
  last_synced_at: string;
}

function makeStageData(total: number, complete: number, firstDate: string | null, lastDate: string | null): PonStageData {
  return {
    total,
    complete,
    pct: total > 0 ? Math.round((complete / total) * 10000) / 100 : 0,
    first_date: firstDate,
    last_date: lastDate,
  };
}

function aggregateStages(pons: PonStageRow[]): Record<BuildStage, PonStageData> {
  const result = {} as Record<BuildStage, PonStageData>;
  for (const stage of BUILD_STAGES) {
    let totalSum = 0;
    let completeSum = 0;
    let firstDate: string | null = null;
    let lastDate: string | null = null;

    for (const pon of pons) {
      const data = pon[stage];
      totalSum += data.total;
      completeSum += data.complete;
      if (data.first_date && (!firstDate || data.first_date < firstDate)) firstDate = data.first_date;
      if (data.last_date && (!lastDate || data.last_date > lastDate)) lastDate = data.last_date;
    }

    result[stage] = makeStageData(totalSum, completeSum, firstDate, lastDate);
  }
  return result;
}

async function handler(
  req: NextApiRequest,
  res: NextApiResponse<PonStagesResponse | { error: string }>
) {
  if (req.method !== 'GET') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const { projectId, zone } = req.query;
  const projectIdStr = Array.isArray(projectId) ? projectId[0] : projectId;
  const zoneFilter = zone ? Number(Array.isArray(zone) ? zone[0] : zone) : null;

  if (!projectIdStr) {
    return res.status(400).json({ error: 'Missing projectId' });
  }

  try {
    const client = await pool.connect();
    try {
      // Get project name
      const projectResult = await client.query<{ project_name: string }>(
        'SELECT project_name FROM projects WHERE id = $1',
        [projectIdStr]
      );

      if (projectResult.rows.length === 0) {
        return res.status(404).json({ error: 'Project not found' });
      }

      const projectName = projectResult.rows[0]!.project_name;

      // Fetch PON stage data
      let query = `
        SELECT zone_no, pon_no,
          permissions_total::text, permissions_approved::text,
          permissions_first_date::text, permissions_last_date::text,
          poles_total::text, poles_planted::text,
          poles_first_date::text, poles_last_date::text,
          cwc_total::text, cwc_complete::text,
          cwc_first_date::text, cwc_last_date::text,
          optical_total::text, optical_complete::text,
          optical_first_date::text, optical_last_date::text,
          atp_total::text, atp_passed::text,
          atp_first_date::text, atp_last_date::text,
          activation_total::text, activation_complete::text,
          activation_first_date::text, activation_last_date::text,
          overall_stage,
          last_synced_at::text
        FROM pon_stage_tracking
        WHERE project_id = $1
      `;
      const params: (string | number)[] = [projectIdStr];

      if (zoneFilter !== null) {
        query += ' AND zone_no = $2';
        params.push(zoneFilter);
      }

      query += ' ORDER BY zone_no, pon_no';

      const result = await client.query<RawRow>(query, params);

      // Build PON rows
      const flatRows: PonStageRow[] = result.rows.map(row => ({
        zone_no: row.zone_no,
        pon_no: row.pon_no,
        permissions: makeStageData(Number(row.permissions_total), Number(row.permissions_approved), row.permissions_first_date, row.permissions_last_date),
        poles: makeStageData(Number(row.poles_total), Number(row.poles_planted), row.poles_first_date, row.poles_last_date),
        cwc: makeStageData(Number(row.cwc_total), Number(row.cwc_complete), row.cwc_first_date, row.cwc_last_date),
        optical: makeStageData(Number(row.optical_total), Number(row.optical_complete), row.optical_first_date, row.optical_last_date),
        atp: makeStageData(Number(row.atp_total), Number(row.atp_passed), row.atp_first_date, row.atp_last_date),
        activation: makeStageData(Number(row.activation_total), Number(row.activation_complete), row.activation_first_date, row.activation_last_date),
        overall_stage: row.overall_stage as OverallStage,
        last_synced_at: row.last_synced_at,
      }));

      // Build zone hierarchy
      const zoneMap = new Map<number, PonStageRow[]>();
      for (const row of flatRows) {
        const existing = zoneMap.get(row.zone_no);
        if (existing) {
          existing.push(row);
        } else {
          zoneMap.set(row.zone_no, [row]);
        }
      }

      const hierarchy: ZoneStageNode[] = [];
      for (const [zoneNo, pons] of zoneMap) {
        hierarchy.push({
          zone_no: zoneNo,
          zone_name: `Zone ${zoneNo}`,
          pons,
          stages: aggregateStages(pons),
        });
      }
      hierarchy.sort((a, b) => a.zone_no - b.zone_no);

      // Build summary
      const allStages = aggregateStages(flatRows);
      let lastSynced: string | null = null;
      for (const row of flatRows) {
        if (row.last_synced_at && (!lastSynced || row.last_synced_at > lastSynced)) {
          lastSynced = row.last_synced_at;
        }
      }

      const response: PonStagesResponse = {
        project_id: projectIdStr,
        project_name: projectName,
        summary: {
          total_pons: flatRows.length,
          stages: allStages,
          last_synced: lastSynced,
        },
        hierarchy,
        flat: flatRows,
      };

      log.info('PON stages fetched', {
        projectId: projectIdStr,
        totalPons: flatRows.length,
        zones: hierarchy.length,
      }, 'PonStages');

      return res.status(200).json(response);
    } finally {
      client.release();
    }
  } catch (error) {
    log.error('Failed to fetch PON stages', { error, projectId: projectIdStr }, 'PonStages');
    return res.status(500).json({
      error: error instanceof Error ? error.message : 'Internal server error',
    });
  }
}

export default withAuth(handler);

/**
 * Construction QA Review API
 *
 * GET  /api/construction-qa/review?id={reviewId}
 *   - Returns full review detail with photos and activity
 *
 * POST /api/construction-qa/review
 *   - Updates review checklist steps and extracted data (Phase 2/3)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth } from '@/lib/auth/middleware';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') return handleGet(req, res);
  if (req.method === 'POST') return handlePost(req, res);
  return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['GET', 'POST']);
}

async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const { id } = req.query;

  if (!id || typeof id !== 'string') {
    return apiResponse.badRequest(res, 'Review id is required');
  }

  try {
    // Fetch review with project name
    const reviews = await sql`
      SELECT
        r.*,
        p.project_name
      FROM construction_qa_reviews r
      JOIN projects p ON p.id = r.project_id
      WHERE r.id = ${id}::uuid
      LIMIT 1
    `;

    if (reviews.length === 0) {
      return apiResponse.notFound(res, 'Review', id);
    }

    const review = reviews[0];

    // Fetch photos
    const photos = await sql`
      SELECT *
      FROM construction_qa_photos
      WHERE review_id = ${id}::uuid
      ORDER BY checklist_step ASC NULLS LAST, created_at ASC
    `;

    // Fetch recent activity (last 50 entries)
    const activity = await sql`
      SELECT *
      FROM construction_qa_activity
      WHERE review_id = ${id}::uuid
      ORDER BY created_at DESC
      LIMIT 50
    `;

    return apiResponse.success(res, {
      review,
      photos,
      activity,
    });
  } catch (error) {
    log.error('Review GET error', { module: 'construction-qa', error: (error as Error).message });

    if ((error as Error).message?.includes('does not exist')) {
      return apiResponse.success(res, { review: null, photos: [], activity: [] });
    }

    return apiResponse.internalError(res, error);
  }
}

async function handlePost(req: NextApiRequest, res: NextApiResponse) {
  try {
    const { reviewId, stepUpdates, extractedDataUpdates, notes, reviewedBy, featureIdUpdate } = req.body;

    if (!reviewId) {
      return apiResponse.badRequest(res, 'reviewId is required');
    }

    // Build SET clauses from step updates
    const setClauses: string[] = ['updated_at = NOW()'];
    const params: (string | number | boolean)[] = [reviewId];
    let paramIdx = 2;

    // Valid step column names (whitelist to prevent SQL injection)
    const validStepColumns = new Set([
      // Civil — Pole Install Capture Checklist (8 steps)
      'civil_step_01_before_photo', 'civil_step_02_during_photo', 'civil_step_03_depth_photo',
      'civil_step_04_end_plates', 'civil_step_05_compaction', 'civil_step_06_level_check',
      'civil_step_07_after_photo', 'civil_step_08_signature',
      // Optical — Cable Stringing (6 steps, unchanged)
      'optical_step_01_cable_route', 'optical_step_02_attachment', 'optical_step_03_slack_coil',
      'optical_step_04_cable_label', 'optical_step_05_no_backfeed', 'optical_step_06_sag_ok',
      // Splicing — Distribution Dome (8 steps)
      'splicing_step_01_dome_on_pole', 'splicing_step_02_dome_label',
      'splicing_step_03_open_dome', 'splicing_step_04_splice_protectors',
      'splicing_step_05_slack_management', 'splicing_step_06_strength_members',
      'splicing_step_07_seals_dustcaps', 'splicing_step_08_pole_id',
      // Splicing — Main Joint (6 steps, numbered 11-16)
      'splicing_step_11_cable_entries', 'splicing_step_12_strength_members',
      'splicing_step_13_tube_routing', 'splicing_step_14_tray_entries',
      'splicing_step_15_coiling_protectors', 'splicing_step_16_readable_labels',
    ]);

    const updatedFields: string[] = [];

    if (stepUpdates && typeof stepUpdates === 'object') {
      for (const [col, val] of Object.entries(stepUpdates)) {
        if (validStepColumns.has(col)) {
          setClauses.push(`${col} = $${paramIdx}`);
          params.push(Boolean(val));
          paramIdx++;
          updatedFields.push(col);
        }
      }
    }

    // Valid extracted data columns
    const validExtractedColumns = new Set([
      'extracted_pole_number', 'extracted_pole_height', 'extracted_cable_type',
      'extracted_joint_type', 'extracted_splice_count',
    ]);

    if (extractedDataUpdates && typeof extractedDataUpdates === 'object') {
      for (const [col, val] of Object.entries(extractedDataUpdates)) {
        if (validExtractedColumns.has(col)) {
          setClauses.push(`${col} = $${paramIdx}`);
          params.push(val as string | number);
          paramIdx++;
          updatedFields.push(col);
        }
      }
    }

    if (notes) {
      setClauses.push(`qa_notes = $${paramIdx}`);
      params.push(notes);
      paramIdx++;
      updatedFields.push('qa_notes');
    }

    // Feature ID rename/reassign
    if (featureIdUpdate && typeof featureIdUpdate === 'string') {
      setClauses.push(`feature_id = $${paramIdx}`);
      params.push(featureIdUpdate.trim());
      paramIdx++;
      updatedFields.push('feature_id');

      // If renaming to a valid pole pattern, try to backfill zone/PON and clear unidentified
      const validPolePattern = /^[A-Z]{3}\.P\./;
      if (validPolePattern.test(featureIdUpdate.trim())) {
        setClauses.push(`workflow_status = CASE WHEN workflow_status = 'unidentified' THEN 'pending' ELSE workflow_status END`);
      }
    }

    // Move to in_review if currently pending
    setClauses.push(`workflow_status = CASE WHEN workflow_status = 'pending' THEN 'in_review' ELSE workflow_status END`);

    // Execute update
    const updateQuery = `
      UPDATE construction_qa_reviews
      SET ${setClauses.join(', ')}
      WHERE id = $1::uuid
      RETURNING id
    `;

    const result = await sql.query(updateQuery, params);

    if (result.length === 0) {
      return apiResponse.notFound(res, 'Review', reviewId);
    }

    // Log activity
    if (updatedFields.length > 0) {
      const eventType = updatedFields.includes('feature_id') ? 'comment_added' : 'step_checked';
      const payload = updatedFields.includes('feature_id')
        ? { action: 'feature_id_renamed', new_feature_id: featureIdUpdate, updated_fields: updatedFields }
        : { updated_fields: updatedFields };

      await sql`
        INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
        VALUES (
          ${reviewId}::uuid,
          ${eventType},
          ${reviewedBy || 'unknown'},
          ${JSON.stringify(payload)}::jsonb
        )
      `;
    }

    return apiResponse.success(res, {
      reviewId,
      updatedFields,
    });
  } catch (error) {
    log.error('Review POST error', { module: 'construction-qa', error: (error as Error).message });
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * Construction QA Features API
 *
 * GET /api/construction-qa/features
 *   - List features with filters, pagination, and stats
 *   - ?action=projects returns project list only
 *
 * Follows apiResponse pattern from @/lib/apiResponse
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse, ErrorCode } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth } from '@/lib/auth/middleware';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['GET']);
  }

  try {
    const { action } = req.query;

    // Return project list
    if (action === 'projects') {
      const projects = await sql`
        SELECT DISTINCT p.id, p.project_name AS name
        FROM projects p
        INNER JOIN construction_qa_reviews r ON r.project_id = p.id
        ORDER BY p.project_name
      `;
      return apiResponse.success(res, { projects });
    }

    // Parse filters
    const projectId = req.query.projectId as string || '';
    const discipline = req.query.discipline as string || 'civil';
    const zoneNo = req.query.zoneNo as string || '';
    const ponNo = req.query.ponNo as string || '';
    const workflowStatus = req.query.workflowStatus as string || '';
    const priority = req.query.priority as string || '';
    const search = req.query.search as string || '';
    const page = Math.max(1, parseInt(req.query.page as string || '1', 10));
    const pageSize = Math.min(200, Math.max(1, parseInt(req.query.pageSize as string || '50', 10)));
    const offset = (page - 1) * pageSize;

    // Build WHERE conditions
    const conditions: string[] = ['r.discipline = $1'];
    const params: (string | number)[] = [discipline];
    let paramIdx = 2;

    if (projectId) {
      conditions.push(`r.project_id = $${paramIdx}::uuid`);
      params.push(projectId);
      paramIdx++;
    }

    if (zoneNo) {
      if (zoneNo === '-1') {
        conditions.push('r.zone_no IS NULL');
      } else {
        conditions.push(`r.zone_no = $${paramIdx}`);
        params.push(parseInt(zoneNo, 10));
        paramIdx++;
      }
    }

    if (ponNo) {
      if (ponNo === '-1') {
        conditions.push('r.pon_no IS NULL');
      } else {
        conditions.push(`r.pon_no = $${paramIdx}`);
        params.push(parseInt(ponNo, 10));
        paramIdx++;
      }
    }

    if (workflowStatus) {
      conditions.push(`r.workflow_status = $${paramIdx}`);
      params.push(workflowStatus);
      paramIdx++;
    }

    if (priority) {
      conditions.push(`r.priority = $${paramIdx}`);
      params.push(priority);
      paramIdx++;
    }

    if (search) {
      conditions.push(`(r.feature_id ILIKE $${paramIdx} OR r.extracted_pole_number ILIKE $${paramIdx})`);
      params.push(`%${search}%`);
      paramIdx++;
    }

    const whereClause = conditions.join(' AND ');

    // Fetch features with project name
    const featuresQuery = `
      SELECT
        r.id,
        r.feature_id,
        r.feature_type,
        r.discipline,
        r.zone_no,
        r.pon_no,
        r.photo_count,
        r.vlm_confidence,
        r.vlm_status,
        r.workflow_status,
        r.qa_decision,
        r.priority,
        r.assigned_to,
        r.created_at,
        r.updated_at,
        p.project_name
      FROM construction_qa_reviews r
      JOIN projects p ON p.id = r.project_id
      WHERE ${whereClause}
      ORDER BY
        CASE r.priority
          WHEN 'urgent' THEN 0
          WHEN 'high' THEN 1
          WHEN 'normal' THEN 2
          WHEN 'low' THEN 3
        END,
        r.updated_at DESC
      LIMIT $${paramIdx} OFFSET $${paramIdx + 1}
    `;

    const countQuery = `
      SELECT COUNT(*) AS total
      FROM construction_qa_reviews r
      WHERE ${whereClause}
    `;

    // Stats query (always filtered by discipline, optionally by project)
    const statsConditions: string[] = ['discipline = $1'];
    const statsParams: (string | number)[] = [discipline];
    let statsParamIdx = 2;

    if (projectId) {
      statsConditions.push(`project_id = $${statsParamIdx}::uuid`);
      statsParams.push(projectId);
      statsParamIdx++;
    }

    const statsWhere = statsConditions.join(' AND ');
    const statsQuery = `
      SELECT
        COUNT(*) AS total,
        COUNT(*) FILTER (WHERE workflow_status = 'pending') AS pending,
        COUNT(*) FILTER (WHERE workflow_status = 'approved') AS approved,
        COUNT(*) FILTER (WHERE workflow_status = 'rejected') AS rejected,
        COUNT(*) FILTER (WHERE workflow_status = 'rework_needed') AS rework_needed,
        COUNT(*) FILTER (WHERE workflow_status = 'escalated') AS escalated,
        COUNT(*) FILTER (WHERE workflow_status = 'unidentified') AS unidentified
      FROM construction_qa_reviews
      WHERE ${statsWhere}
    `;

    // Execute all queries in parallel
    const [features, countResult, statsResult] = await Promise.all([
      sql.query(featuresQuery, [...params, pageSize, offset]),
      sql.query(countQuery, params),
      sql.query(statsQuery, statsParams),
    ]);

    const total = Number(countResult[0]?.total || 0);
    const statsRow = statsResult[0] || {};

    return apiResponse.success(res, {
      features,
      stats: {
        total: Number(statsRow.total || 0),
        pending: Number(statsRow.pending || 0),
        approved: Number(statsRow.approved || 0),
        rejected: Number(statsRow.rejected || 0),
        rework_needed: Number(statsRow.rework_needed || 0),
        escalated: Number(statsRow.escalated || 0),
        unidentified: Number(statsRow.unidentified || 0),
      },
      pagination: {
        page,
        pageSize,
        total,
        totalPages: Math.ceil(total / pageSize),
      },
    });
  } catch (error) {
    log.error('Features API error', { module: 'construction-qa', error: (error as Error).message });

    // If table doesn't exist yet (pre-migration), return empty data
    if ((error as Error).message?.includes('does not exist')) {
      return apiResponse.success(res, {
        features: [],
        stats: { total: 0, pending: 0, approved: 0, rejected: 0, rework_needed: 0, escalated: 0, unidentified: 0 },
        pagination: { page: 1, pageSize: 50, total: 0, totalPages: 0 },
      });
    }

    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * Phase 1: Prerequisites
 * Verify photos exist, feature data is loaded, and VLM is ready.
 */

import { CheckCircle, XCircle, AlertTriangle, Camera, Database, Cpu } from 'lucide-react';
import type { ChecklistStep } from '../../types';

interface Props {
  review: Record<string, unknown>;
  photos: Array<{ checklist_step: number | null; [key: string]: unknown }>;
  checklist: readonly ChecklistStep[];
}

export function PhasePrerequisites({ review, photos, checklist }: Props) {
  const photoCount = photos.length;
  const requiredSteps = checklist.filter(s => s.required);
  const coveredSteps = new Set(photos.map(p => p.checklist_step).filter(Boolean));
  const missingRequired = requiredSteps.filter(s => !coveredSteps.has(s.step));
  const vlmStatus = review.vlm_status as string;
  const vlmReady = vlmStatus === 'completed';

  const checks = [
    {
      label: 'Photos available',
      description: `${photoCount} photo(s) loaded from source`,
      passed: photoCount > 0,
      icon: Camera,
    },
    {
      label: 'Required steps covered',
      description: missingRequired.length === 0
        ? `All ${requiredSteps.length} required steps have photos`
        : `Missing: ${missingRequired.map(s => `Step ${s.step} (${s.label})`).join(', ')}`,
      passed: missingRequired.length === 0,
      warning: missingRequired.length > 0 && photoCount > 0,
      icon: CheckCircle,
    },
    {
      label: 'Feature data loaded',
      description: review.feature_id ? `Feature: ${review.feature_id}` : 'No feature ID',
      passed: Boolean(review.feature_id),
      icon: Database,
    },
    {
      label: 'AI validation',
      description: vlmReady
        ? `VLM completed — ${review.vlm_confidence != null ? `${Math.round(Number(review.vlm_confidence) * 100)}% confidence` : 'no score'}`
        : vlmStatus === 'processing' ? 'VLM processing in progress...'
        : vlmStatus === 'failed' ? 'VLM processing failed — manual review required'
        : 'VLM not yet run — will process when triggered',
      passed: vlmReady,
      warning: vlmStatus === 'processing',
      icon: Cpu,
    },
  ];

  const allPassed = checks.every(c => c.passed);

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-lg font-semibold text-white mb-1">Prerequisites Check</h2>
        <p className="text-sm text-gray-400">
          Verify that all required data is available before starting the review.
        </p>
      </div>

      <div className="space-y-3">
        {checks.map((check, i) => {
          const Icon = check.icon;
          const StatusIcon = check.passed ? CheckCircle : check.warning ? AlertTriangle : XCircle;
          const statusColor = check.passed ? 'text-green-400' : check.warning ? 'text-yellow-400' : 'text-red-400';
          const borderColor = check.passed ? 'border-green-500/30' : check.warning ? 'border-yellow-500/30' : 'border-red-500/30';

          return (
            <div
              key={i}
              className={`flex items-start gap-4 p-4 rounded-lg border ${borderColor} bg-[var(--card-bg)]`}
            >
              <Icon className={`w-5 h-5 mt-0.5 ${statusColor}`} />
              <div className="flex-1">
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium text-white">{check.label}</span>
                  <StatusIcon className={`w-4 h-4 ${statusColor}`} />
                </div>
                <p className="text-xs text-gray-400 mt-0.5">{check.description}</p>
              </div>
            </div>
          );
        })}
      </div>

      {/* Step coverage summary */}
      <div className="border-t border-[var(--border-color)] pt-4">
        <h3 className="text-sm font-medium text-gray-300 mb-3">Checklist Step Coverage</h3>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
          {checklist.map(step => {
            const hasCoverage = coveredSteps.has(step.step);
            return (
              <div
                key={step.step}
                className={`flex items-center gap-2 p-2 rounded text-xs ${
                  hasCoverage
                    ? 'bg-green-500/10 text-green-400'
                    : step.required
                      ? 'bg-red-500/10 text-red-400'
                      : 'bg-gray-500/10 text-gray-500'
                }`}
              >
                {hasCoverage ? <CheckCircle className="w-3 h-3" /> : <XCircle className="w-3 h-3" />}
                <span>S{step.step}: {step.label}</span>
                {!step.required && <span className="text-gray-600">(opt)</span>}
              </div>
            );
          })}
        </div>
      </div>

      {allPassed && (
        <div className="p-4 bg-green-500/10 border border-green-500/30 rounded-lg">
          <p className="text-sm text-green-400 font-medium">
            All prerequisites met — proceed to Photo Review.
          </p>
        </div>
      )}

      {!allPassed && photoCount > 0 && (
        <div className="p-4 bg-yellow-500/10 border border-yellow-500/30 rounded-lg">
          <p className="text-sm text-yellow-400 font-medium">
            Some prerequisites are not met, but you can still proceed with manual review.
          </p>
        </div>
      )}
    </div>
  );
}

/**
 * Phase 2: Photo Review
 * Walk through each checklist step, view assigned photos, toggle checked state.
 * Click any photo to open full-screen lightbox with zoom.
 */

'use client';

import { useState, useMemo } from 'react';
import { CheckCircle, ChevronDown, ChevronRight, Image, AlertTriangle, Maximize2 } from 'lucide-react';
import type { ChecklistStep, Discipline } from '../../types';
import { PhotoLightbox } from './PhotoLightbox';

interface PhotoData {
  id: string;
  storage_key: string;
  source: string;
  filename: string | null;
  checklist_step: number | null;
  vlm_valid: boolean | null;
  vlm_confidence: number | null;
  vlm_issues: string[];
  vlm_feedback: string | null;
  manual_status: string | null;
  needs_retake: boolean;
}

interface Props {
  review: { discipline: Discipline; [key: string]: unknown };
  photos: PhotoData[];
  checklist: readonly ChecklistStep[];
  checkedSteps: Record<string, boolean>;
  onStepChange: (col: string, val: boolean) => void;
}

export function PhasePhotoReview({ review, photos, checklist, checkedSteps, onStepChange }: Props) {
  const [expandedStep, setExpandedStep] = useState<number | null>(1);
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null);

  // Group photos by step
  const photosByStep = new Map<number, PhotoData[]>();
  const unassigned: PhotoData[] = [];
  for (const photo of photos) {
    if (photo.checklist_step != null) {
      if (!photosByStep.has(photo.checklist_step)) photosByStep.set(photo.checklist_step, []);
      photosByStep.get(photo.checklist_step)!.push(photo);
    } else {
      unassigned.push(photo);
    }
  }

  // Flat list of all photos for lightbox navigation (step photos first, then unassigned)
  const allPhotos = useMemo(() => {
    const ordered: PhotoData[] = [];
    for (const step of checklist) {
      const stepPhotos = photosByStep.get(step.step) || [];
      ordered.push(...stepPhotos);
    }
    ordered.push(...unassigned);
    return ordered;
  }, [photos, checklist]);

  const openLightbox = (photoId: string) => {
    const idx = allPhotos.findIndex(p => p.id === photoId);
    if (idx >= 0) setLightboxIndex(idx);
  };

  const getStepColumn = (step: number): string => {
    const pad = String(step).padStart(2, '0');
    const stepNames: Record<string, Record<number, string>> = {
      civil: { 1: 'before_photo', 2: 'during_photo', 3: 'depth_photo', 4: 'end_plates', 5: 'compaction', 6: 'level_check', 7: 'after_photo', 8: 'signature' },
      optical: { 1: 'cable_route', 2: 'attachment', 3: 'slack_coil', 4: 'cable_label', 5: 'no_backfeed', 6: 'sag_ok' },
      splicing: { 1: 'dome_on_pole', 2: 'dome_label', 3: 'open_dome', 4: 'splice_protectors', 5: 'slack_management', 6: 'strength_members', 7: 'seals_dustcaps', 8: 'pole_id', 11: 'cable_entries', 12: 'strength_members', 13: 'tube_routing', 14: 'tray_entries', 15: 'coiling_protectors', 16: 'readable_labels' },
    };
    return `${review.discipline}_step_${pad}_${stepNames[review.discipline]?.[step] || 'unknown'}`;
  };

  return (
    <div className="space-y-4">
      <div>
        <h2 className="text-lg font-semibold text-white mb-1">Photo Review</h2>
        <p className="text-sm text-gray-400">
          Review each checklist step and verify photos meet quality standards. Click any photo to enlarge.
        </p>
      </div>

      {/* Checklist Steps */}
      <div className="space-y-2">
        {checklist.map(step => {
          const stepPhotos = photosByStep.get(step.step) || [];
          const col = getStepColumn(step.step);
          const isChecked = checkedSteps[col] || false;
          const isExpanded = expandedStep === step.step;
          const avgConfidence = stepPhotos.length > 0
            ? stepPhotos.reduce((sum, p) => sum + (p.vlm_confidence || 0), 0) / stepPhotos.length
            : null;

          return (
            <div
              key={step.step}
              className={`border rounded-lg overflow-hidden ${
                isChecked ? 'border-green-500/30' : 'border-[var(--border-color)]'
              }`}
            >
              {/* Step Header */}
              <div
                onClick={() => setExpandedStep(isExpanded ? null : step.step)}
                className="flex items-center gap-3 px-4 py-3 cursor-pointer hover:bg-[var(--hover-bg)] transition-colors"
              >
                {/* Checkbox */}
                <button
                  onClick={e => { e.stopPropagation(); onStepChange(col, !isChecked); }}
                  className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${
                    isChecked
                      ? 'bg-green-600 border-green-600'
                      : 'border-gray-600 hover:border-gray-400'
                  }`}
                >
                  {isChecked && <CheckCircle className="w-3.5 h-3.5 text-white" />}
                </button>

                {/* Step Info */}
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-medium text-white">
                      Step {step.step}: {step.label}
                    </span>
                    {!step.required && (
                      <span className="text-xs text-gray-600 bg-gray-800 px-1.5 py-0.5 rounded">optional</span>
                    )}
                  </div>
                  <p className="text-xs text-gray-500 mt-0.5">{step.vlmCheck}</p>
                </div>

                {/* Photo count + VLM score */}
                <div className="flex items-center gap-3">
                  <div className="flex items-center gap-1 text-xs text-gray-400">
                    <Image className="w-3 h-3" />
                    {stepPhotos.length}
                  </div>
                  {avgConfidence !== null && (
                    <span className={`text-xs font-mono ${
                      avgConfidence >= 0.8 ? 'text-green-400' :
                      avgConfidence >= 0.6 ? 'text-yellow-400' : 'text-red-400'
                    }`}>
                      {Math.round(avgConfidence * 100)}%
                    </span>
                  )}
                  {isExpanded ? <ChevronDown className="w-4 h-4 text-gray-500" /> : <ChevronRight className="w-4 h-4 text-gray-500" />}
                </div>
              </div>

              {/* Expanded: Photo Grid */}
              {isExpanded && (
                <div className="px-4 pb-4 border-t border-[var(--border-color)]">
                  {step.notes && (
                    <p className="text-xs text-gray-500 py-2 italic">{step.notes}</p>
                  )}

                  {stepPhotos.length === 0 ? (
                    <div className="text-center py-6 text-gray-500 text-sm">
                      No photos assigned to this step
                    </div>
                  ) : (
                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3 pt-3">
                      {stepPhotos.map(photo => (
                        <div
                          key={photo.id}
                          onClick={() => openLightbox(photo.id)}
                          className="relative rounded-lg overflow-hidden border cursor-pointer transition-all hover:border-blue-500 hover:ring-2 hover:ring-blue-500/30 border-[var(--border-color)] group"
                        >
                          {/* Photo thumbnail */}
                          <div className="aspect-square bg-gray-900 flex items-center justify-center">
                            <img
                              src={`/api/construction-qa/photo-proxy?key=${encodeURIComponent(photo.storage_key)}&source=${photo.source}`}
                              alt={photo.filename || 'Photo'}
                              className="w-full h-full object-cover"
                              loading="lazy"
                            />
                          </div>

                          {/* Enlarge indicator on hover */}
                          <div className="absolute inset-0 bg-black/0 group-hover:bg-black/30 transition-colors flex items-center justify-center">
                            <Maximize2 className="w-6 h-6 text-white opacity-0 group-hover:opacity-100 transition-opacity" />
                          </div>

                          {/* VLM badge */}
                          {photo.vlm_confidence != null && (
                            <div className={`absolute top-1 right-1 px-1.5 py-0.5 rounded text-[10px] font-mono font-bold ${
                              photo.vlm_confidence >= 0.8 ? 'bg-green-600/90 text-white' :
                              photo.vlm_confidence >= 0.6 ? 'bg-yellow-600/90 text-white' :
                              'bg-red-600/90 text-white'
                            }`}>
                              {Math.round(photo.vlm_confidence * 100)}%
                            </div>
                          )}

                          {/* Retake warning */}
                          {photo.needs_retake && (
                            <div className="absolute top-1 left-1">
                              <AlertTriangle className="w-4 h-4 text-orange-400" />
                            </div>
                          )}

                          {/* Filename at bottom */}
                          <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent px-2 py-1">
                            <div className="text-[10px] text-gray-300 truncate">{photo.filename}</div>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Unassigned Photos */}
      {unassigned.length > 0 && (
        <div className="border border-yellow-500/30 rounded-lg p-4">
          <h3 className="text-sm font-medium text-yellow-400 mb-2">
            Unassigned Photos ({unassigned.length})
          </h3>
          <p className="text-xs text-gray-500 mb-3">
            These photos are not linked to any checklist step yet. Click to enlarge.
          </p>
          <div className="grid grid-cols-3 md:grid-cols-6 gap-2">
            {unassigned.map(photo => (
              <div
                key={photo.id}
                onClick={() => openLightbox(photo.id)}
                className="aspect-square bg-gray-900 rounded overflow-hidden cursor-pointer hover:ring-2 hover:ring-blue-500/30 transition-all group relative"
              >
                <img
                  src={`/api/construction-qa/photo-proxy?key=${encodeURIComponent(photo.storage_key)}&source=${photo.source}`}
                  alt={photo.filename || 'Photo'}
                  className="w-full h-full object-cover"
                  loading="lazy"
                />
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/30 transition-colors flex items-center justify-center">
                  <Maximize2 className="w-5 h-5 text-white opacity-0 group-hover:opacity-100 transition-opacity" />
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Lightbox */}
      {lightboxIndex !== null && (
        <PhotoLightbox
          photos={allPhotos}
          initialIndex={lightboxIndex}
          onClose={() => setLightboxIndex(null)}
        />
      )}
    </div>
  );
}

/**
 * Phase 3: Data Validation
 * Compare VLM-extracted data against QField database values.
 * Allows manual overrides for incorrect extractions.
 */

'use client';

import { CheckCircle, XCircle, Edit3 } from 'lucide-react';
import type { Discipline } from '../../types';

interface Props {
  review: {
    discipline: Discipline;
    feature_id: string;
    extracted_pole_number?: string | null;
    extracted_pole_height?: string | null;
    extracted_cable_type?: string | null;
    extracted_joint_type?: string | null;
    extracted_splice_count?: number | null;
    pole_latitude?: number | null;
    pole_longitude?: number | null;
    pole_material?: string | null;
    pole_height_m?: number | null;
    span_from_pole?: string | null;
    span_to_pole?: string | null;
    span_length_m?: number | null;
    span_cable_size?: string | null;
    joint_cable_cap?: string | null;
    [key: string]: unknown;
  };
  overrides: Record<string, string>;
  onOverride: (field: string, value: string) => void;
}

interface ValidationField {
  label: string;
  extractedField: string;
  referenceField: string;
  extractedValue: string | number | null | undefined;
  referenceValue: string | number | null | undefined;
}

export function PhaseDataValidation({ review, overrides, onOverride }: Props) {
  const fields = getValidationFields(review);

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-lg font-semibold text-white mb-1">Data Validation</h2>
        <p className="text-sm text-gray-400">
          Compare AI-extracted data with QField records. Override incorrect values if needed.
        </p>
      </div>

      <div className="space-y-3">
        {fields.map((field, i) => {
          const extracted = overrides[field.extractedField] ?? String(field.extractedValue ?? '—');
          const reference = String(field.referenceValue ?? '—');
          const matches = extracted.toLowerCase() === reference.toLowerCase() || (extracted === '—' && reference === '—');
          const hasOverride = field.extractedField in overrides;

          return (
            <div
              key={i}
              className={`grid grid-cols-12 gap-4 items-center p-3 rounded-lg border ${
                matches ? 'border-green-500/20' : 'border-red-500/20'
              }`}
            >
              {/* Label */}
              <div className="col-span-3">
                <span className="text-sm font-medium text-gray-300">{field.label}</span>
              </div>

              {/* AI Extracted */}
              <div className="col-span-3">
                <div className="text-xs text-gray-500 mb-0.5">AI Extracted</div>
                <div className="flex items-center gap-2">
                  <input
                    type="text"
                    value={overrides[field.extractedField] ?? String(field.extractedValue ?? '')}
                    onChange={e => onOverride(field.extractedField, e.target.value)}
                    className="w-full bg-gray-900 border border-[var(--border-color)] rounded px-2 py-1 text-sm text-white"
                    placeholder="—"
                  />
                  {hasOverride && (
                    <Edit3 className="w-3 h-3 text-yellow-400 flex-shrink-0" aria-label="Manually overridden" />
                  )}
                </div>
              </div>

              {/* Reference (QField) */}
              <div className="col-span-3">
                <div className="text-xs text-gray-500 mb-0.5">QField Reference</div>
                <div className="text-sm text-gray-300 px-2 py-1">{reference}</div>
              </div>

              {/* Match Status */}
              <div className="col-span-3 flex items-center gap-2">
                {matches ? (
                  <>
                    <CheckCircle className="w-4 h-4 text-green-400" />
                    <span className="text-xs text-green-400">Match</span>
                  </>
                ) : (
                  <>
                    <XCircle className="w-4 h-4 text-red-400" />
                    <span className="text-xs text-red-400">Mismatch</span>
                  </>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {fields.every(f => {
        const ext = overrides[f.extractedField] ?? String(f.extractedValue ?? '—');
        const ref = String(f.referenceValue ?? '—');
        return ext.toLowerCase() === ref.toLowerCase() || (ext === '—' && ref === '—');
      }) ? (
        <div className="p-4 bg-green-500/10 border border-green-500/30 rounded-lg">
          <p className="text-sm text-green-400 font-medium">
            All extracted data matches QField records.
          </p>
        </div>
      ) : (
        <div className="p-4 bg-yellow-500/10 border border-yellow-500/30 rounded-lg">
          <p className="text-sm text-yellow-400 font-medium">
            Some fields have mismatches. Review and override if the AI extraction is incorrect.
          </p>
        </div>
      )}
    </div>
  );
}

function getValidationFields(review: Props['review']): ValidationField[] {
  switch (review.discipline) {
    case 'civil':
      return [
        {
          label: 'Pole Number',
          extractedField: 'extracted_pole_number',
          referenceField: 'feature_id',
          extractedValue: review.extracted_pole_number,
          referenceValue: review.feature_id,
        },
        {
          label: 'Pole Height',
          extractedField: 'extracted_pole_height',
          referenceField: 'pole_height_m',
          extractedValue: review.extracted_pole_height,
          referenceValue: review.pole_height_m,
        },
        {
          label: 'Material',
          extractedField: 'pole_material',
          referenceField: 'pole_material',
          extractedValue: review.pole_material,
          referenceValue: review.pole_material,
        },
      ];

    case 'optical':
      return [
        {
          label: 'Cable Type',
          extractedField: 'extracted_cable_type',
          referenceField: 'span_cable_size',
          extractedValue: review.extracted_cable_type,
          referenceValue: review.span_cable_size,
        },
        {
          label: 'From Pole',
          extractedField: 'span_from_pole',
          referenceField: 'span_from_pole',
          extractedValue: review.span_from_pole,
          referenceValue: review.span_from_pole,
        },
        {
          label: 'To Pole',
          extractedField: 'span_to_pole',
          referenceField: 'span_to_pole',
          extractedValue: review.span_to_pole,
          referenceValue: review.span_to_pole,
        },
        {
          label: 'Span Length (m)',
          extractedField: 'span_length_m',
          referenceField: 'span_length_m',
          extractedValue: review.span_length_m,
          referenceValue: review.span_length_m,
        },
      ];

    case 'splicing':
      return [
        {
          label: 'Joint Type',
          extractedField: 'extracted_joint_type',
          referenceField: 'joint_cable_cap',
          extractedValue: review.extracted_joint_type,
          referenceValue: review.joint_cable_cap,
        },
        {
          label: 'Splice Count',
          extractedField: 'extracted_splice_count',
          referenceField: 'extracted_splice_count',
          extractedValue: review.extracted_splice_count,
          referenceValue: review.extracted_splice_count,
        },
      ];

    default:
      return [];
  }
}

/**
 * Phase 4: Final Decision
 * PASS / FAIL / REWORK_NEEDED with reason codes and notes.
 */

'use client';

import { CheckCircle, XCircle, AlertTriangle } from 'lucide-react';
import type {
  Discipline,
  QaDecision,
  QaReasonCode,
  ChecklistStep,
} from '../../types';
import { REASON_CODE_LABELS } from '../../types/construction.types';

interface Props {
  review: { discipline: Discipline; vlm_confidence: number | null; [key: string]: unknown };
  checklist: readonly ChecklistStep[];
  checkedSteps: Record<string, boolean>;
  decision: QaDecision | null;
  reasonCodes: QaReasonCode[];
  notes: string;
  onDecisionChange: (d: QaDecision) => void;
  onReasonCodesChange: (codes: QaReasonCode[]) => void;
  onNotesChange: (n: string) => void;
}

const DECISIONS: { key: QaDecision; label: string; description: string; color: string; icon: typeof CheckCircle }[] = [
  {
    key: 'PASS',
    label: 'PASS',
    description: 'Feature meets all quality requirements',
    color: 'border-green-500 bg-green-500/10 text-green-400',
    icon: CheckCircle,
  },
  {
    key: 'REWORK_NEEDED',
    label: 'REWORK',
    description: 'Send back to field for corrections',
    color: 'border-orange-500 bg-orange-500/10 text-orange-400',
    icon: AlertTriangle,
  },
  {
    key: 'FAIL',
    label: 'FAIL',
    description: 'Feature fails quality standards permanently',
    color: 'border-red-500 bg-red-500/10 text-red-400',
    icon: XCircle,
  },
];

export function PhaseFinalDecision({
  review,
  checklist,
  checkedSteps,
  decision,
  reasonCodes,
  notes,
  onDecisionChange,
  onReasonCodesChange,
  onNotesChange,
}: Props) {
  // Count checked steps
  const totalSteps = checklist.length;
  const checkedCount = Object.values(checkedSteps).filter(Boolean).length;
  const requiredSteps = checklist.filter(s => s.required);
  const requiredCheckedCount = requiredSteps.filter(s => {
    const key = Object.keys(checkedSteps).find(k => k.includes(`_step_${String(s.step).padStart(2, '0')}_`));
    return key ? checkedSteps[key] : false;
  }).length;

  // Get reason codes for this discipline
  const disciplinePrefix = review.discipline.toUpperCase();
  const availableReasonCodes = Object.keys(REASON_CODE_LABELS)
    .filter(code => code.startsWith(disciplinePrefix)) as QaReasonCode[];

  const toggleReasonCode = (code: QaReasonCode) => {
    if (reasonCodes.includes(code)) {
      onReasonCodesChange(reasonCodes.filter(c => c !== code));
    } else {
      onReasonCodesChange([...reasonCodes, code]);
    }
  };

  // Auto-suggest decision based on checklist completion
  const suggestedDecision: QaDecision =
    requiredCheckedCount === requiredSteps.length && (review.vlm_confidence == null || Number(review.vlm_confidence) >= 0.6)
      ? 'PASS'
      : 'REWORK_NEEDED';

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-lg font-semibold text-white mb-1">Final Decision</h2>
        <p className="text-sm text-gray-400">
          Make a final QA decision based on the photo review and data validation.
        </p>
      </div>

      {/* Summary stats */}
      <div className="grid grid-cols-3 gap-4">
        <div className="p-3 bg-gray-900 rounded-lg text-center">
          <div className="text-2xl font-bold text-white">{checkedCount}/{totalSteps}</div>
          <div className="text-xs text-gray-500">Steps Checked</div>
        </div>
        <div className="p-3 bg-gray-900 rounded-lg text-center">
          <div className="text-2xl font-bold text-white">{requiredCheckedCount}/{requiredSteps.length}</div>
          <div className="text-xs text-gray-500">Required Steps</div>
        </div>
        <div className="p-3 bg-gray-900 rounded-lg text-center">
          <div className={`text-2xl font-bold ${
            review.vlm_confidence == null ? 'text-gray-500' :
            Number(review.vlm_confidence) >= 0.8 ? 'text-green-400' :
            Number(review.vlm_confidence) >= 0.6 ? 'text-yellow-400' : 'text-red-400'
          }`}>
            {review.vlm_confidence != null ? `${Math.round(Number(review.vlm_confidence) * 100)}%` : '—'}
          </div>
          <div className="text-xs text-gray-500">AI Confidence</div>
        </div>
      </div>

      {/* AI Suggestion */}
      <div className="p-3 bg-blue-500/10 border border-blue-500/30 rounded-lg">
        <p className="text-sm text-blue-400">
          AI suggestion: <strong>{suggestedDecision}</strong> based on checklist completion and VLM confidence.
        </p>
      </div>

      {/* Decision Buttons */}
      <div className="grid grid-cols-3 gap-3">
        {DECISIONS.map(d => {
          const Icon = d.icon;
          const isSelected = decision === d.key;
          return (
            <button
              key={d.key}
              onClick={() => onDecisionChange(d.key)}
              className={`p-4 rounded-lg border-2 transition-all text-center ${
                isSelected ? d.color : 'border-[var(--border-color)] text-gray-500 hover:border-gray-500'
              }`}
            >
              <Icon className={`w-8 h-8 mx-auto mb-2 ${isSelected ? '' : 'opacity-50'}`} />
              <div className="text-lg font-bold">{d.label}</div>
              <div className="text-xs mt-1 opacity-75">{d.description}</div>
            </button>
          );
        })}
      </div>

      {/* Reason Codes (for FAIL / REWORK) */}
      {decision && decision !== 'PASS' && (
        <div className="space-y-3">
          <h3 className="text-sm font-medium text-gray-300">Reason Codes</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
            {availableReasonCodes.map(code => {
              const isSelected = reasonCodes.includes(code);
              return (
                <button
                  key={code}
                  onClick={() => toggleReasonCode(code)}
                  className={`text-left p-2 rounded border text-xs transition-colors ${
                    isSelected
                      ? 'border-red-500/50 bg-red-500/10 text-red-300'
                      : 'border-[var(--border-color)] text-gray-400 hover:border-gray-500'
                  }`}
                >
                  <div className="flex items-center gap-2">
                    <div className={`w-3 h-3 rounded-sm border ${isSelected ? 'bg-red-500 border-red-500' : 'border-gray-600'}`} />
                    <span>{REASON_CODE_LABELS[code]}</span>
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Notes */}
      <div className="space-y-2">
        <label className="text-sm font-medium text-gray-300">
          Notes {decision && decision !== 'PASS' && <span className="text-red-400">*</span>}
        </label>
        <textarea
          value={notes}
          onChange={e => onNotesChange(e.target.value)}
          rows={4}
          className="w-full bg-gray-900 border border-[var(--border-color)] rounded-lg px-3 py-2 text-sm text-white placeholder-gray-600 resize-none"
          placeholder={decision === 'PASS' ? 'Optional notes...' : 'Required: Describe the issues found...'}
        />
      </div>
    </div>
  );
}

/**
 * Phase 5: Feedback
 * Shows QA result summary and WhatsApp feedback status.
 */

import { CheckCircle, XCircle, AlertTriangle, MessageSquare, Clock } from 'lucide-react';
import type { QaDecision, WorkflowStatus } from '../../types';

interface Props {
  review: {
    workflow_status: WorkflowStatus;
    qa_decision: QaDecision | null;
    qa_decision_at: string | null;
    qa_decision_by: string | null;
    qa_notes: string | null;
    qa_reason_code: string | null;
    wa_feedback_sent_at: string | null;
    wa_feedback_message: string | null;
    feature_id: string;
    discipline: string;
    project_name: string;
    [key: string]: unknown;
  };
}

export function PhaseFeedback({ review }: Props) {
  const decisionIcon = review.qa_decision === 'PASS'
    ? CheckCircle
    : review.qa_decision === 'FAIL'
      ? XCircle
      : review.qa_decision === 'REWORK_NEEDED'
        ? AlertTriangle
        : Clock;

  const DecisionIcon = decisionIcon;

  const decisionColor = review.qa_decision === 'PASS'
    ? 'text-green-400'
    : review.qa_decision === 'FAIL'
      ? 'text-red-400'
      : review.qa_decision === 'REWORK_NEEDED'
        ? 'text-orange-400'
        : 'text-gray-400';

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-lg font-semibold text-white mb-1">Review Complete</h2>
        <p className="text-sm text-gray-400">
          Summary of the QA decision and feedback status.
        </p>
      </div>

      {/* Decision Summary */}
      <div className={`p-6 rounded-lg border-2 text-center ${
        review.qa_decision === 'PASS' ? 'border-green-500/50 bg-green-500/10' :
        review.qa_decision === 'FAIL' ? 'border-red-500/50 bg-red-500/10' :
        review.qa_decision === 'REWORK_NEEDED' ? 'border-orange-500/50 bg-orange-500/10' :
        'border-gray-500/50 bg-gray-500/10'
      }`}>
        <DecisionIcon className={`w-16 h-16 mx-auto mb-3 ${decisionColor}`} />
        <h3 className={`text-2xl font-bold ${decisionColor}`}>
          {review.qa_decision || 'PENDING'}
        </h3>
        <p className="text-sm text-gray-400 mt-2">
          {review.feature_id} · {review.discipline} · {review.project_name}
        </p>
        {review.qa_decision_at && (
          <p className="text-xs text-gray-500 mt-1">
            Decided {new Date(review.qa_decision_at).toLocaleString()}
            {review.qa_decision_by && ` by ${review.qa_decision_by}`}
          </p>
        )}
      </div>

      {/* Notes */}
      {review.qa_notes && (
        <div className="p-4 bg-gray-900 rounded-lg">
          <h3 className="text-sm font-medium text-gray-300 mb-2">Decision Notes</h3>
          <p className="text-sm text-gray-400 whitespace-pre-wrap">{review.qa_notes}</p>
        </div>
      )}

      {/* Reason Code */}
      {review.qa_reason_code && (
        <div className="p-4 bg-gray-900 rounded-lg">
          <h3 className="text-sm font-medium text-gray-300 mb-2">Reason Code</h3>
          <span className="px-2 py-1 bg-red-500/20 text-red-400 rounded text-xs">
            {review.qa_reason_code.replace(/_/g, ' ')}
          </span>
        </div>
      )}

      {/* WhatsApp Feedback Status */}
      <div className={`p-4 rounded-lg border ${
        review.wa_feedback_sent_at
          ? 'border-green-500/30 bg-green-500/5'
          : 'border-gray-500/30 bg-gray-500/5'
      }`}>
        <div className="flex items-center gap-3">
          <MessageSquare className={`w-5 h-5 ${review.wa_feedback_sent_at ? 'text-green-400' : 'text-gray-500'}`} />
          <div>
            <h3 className="text-sm font-medium text-gray-300">
              WhatsApp Feedback
            </h3>
            {review.wa_feedback_sent_at ? (
              <p className="text-xs text-green-400 mt-0.5">
                Sent {new Date(review.wa_feedback_sent_at).toLocaleString()}
              </p>
            ) : review.qa_decision === 'PASS' ? (
              <p className="text-xs text-gray-500 mt-0.5">
                No feedback needed — feature passed QA.
              </p>
            ) : (
              <p className="text-xs text-gray-500 mt-0.5">
                Feedback not yet sent to technician.
              </p>
            )}
          </div>
        </div>

        {review.wa_feedback_message && (
          <div className="mt-3 p-3 bg-gray-900 rounded text-xs text-gray-400 whitespace-pre-wrap font-mono">
            {review.wa_feedback_message}
          </div>
        )}
      </div>

      {/* Actions */}
      {!review.qa_decision && (
        <div className="p-4 bg-yellow-500/10 border border-yellow-500/30 rounded-lg">
          <p className="text-sm text-yellow-400">
            No decision has been made yet. Go back to the Decision phase to submit your review.
          </p>
        </div>
      )}
    </div>
  );
}

/**
 * PhotoLightbox — Full-screen photo viewer with zoom and navigation
 *
 * Features:
 *   - Click photo to open full-screen overlay
 *   - Zoom in/out with buttons and mouse wheel
 *   - Pan when zoomed in (click-drag)
 *   - Navigate between photos with arrows
 *   - Close with X, Escape, or click backdrop
 */

'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import { X, ZoomIn, ZoomOut, ChevronLeft, ChevronRight, RotateCcw } from 'lucide-react';

interface LightboxPhoto {
  id: string;
  storage_key: string;
  source: string;
  filename: string | null;
  vlm_confidence: number | null;
  vlm_feedback: string | null;
}

interface Props {
  photos: LightboxPhoto[];
  initialIndex: number;
  onClose: () => void;
}

const MIN_ZOOM = 1;
const MAX_ZOOM = 5;
const ZOOM_STEP = 0.5;

export function PhotoLightbox({ photos, initialIndex, onClose }: Props) {
  const [currentIndex, setCurrentIndex] = useState(initialIndex);
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);

  const photo = photos[currentIndex];
  if (!photo) return null;

  const resetView = () => {
    setZoom(1);
    setPan({ x: 0, y: 0 });
  };

  const goNext = useCallback(() => {
    if (currentIndex < photos.length - 1) {
      setCurrentIndex(prev => prev + 1);
      resetView();
    }
  }, [currentIndex, photos.length]);

  const goPrev = useCallback(() => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
      resetView();
    }
  }, [currentIndex]);

  const zoomIn = () => setZoom(prev => Math.min(prev + ZOOM_STEP, MAX_ZOOM));
  const zoomOut = () => {
    setZoom(prev => {
      const next = Math.max(prev - ZOOM_STEP, MIN_ZOOM);
      if (next === MIN_ZOOM) setPan({ x: 0, y: 0 });
      return next;
    });
  };

  // Keyboard navigation
  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'ArrowRight') goNext();
      if (e.key === 'ArrowLeft') goPrev();
      if (e.key === '+' || e.key === '=') zoomIn();
      if (e.key === '-') zoomOut();
      if (e.key === '0') resetView();
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [goNext, goPrev, onClose]);

  // Mouse wheel zoom
  const handleWheel = useCallback((e: React.WheelEvent) => {
    e.preventDefault();
    if (e.deltaY < 0) {
      setZoom(prev => Math.min(prev + ZOOM_STEP * 0.5, MAX_ZOOM));
    } else {
      setZoom(prev => {
        const next = Math.max(prev - ZOOM_STEP * 0.5, MIN_ZOOM);
        if (next === MIN_ZOOM) setPan({ x: 0, y: 0 });
        return next;
      });
    }
  }, []);

  // Pan with drag
  const handleMouseDown = (e: React.MouseEvent) => {
    if (zoom <= 1) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || zoom <= 1) return;
    setPan({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };

  const handleMouseUp = () => setIsDragging(false);

  // Backdrop click to close (only if not dragging)
  const handleBackdropClick = (e: React.MouseEvent) => {
    if (e.target === containerRef.current && !isDragging) {
      onClose();
    }
  };

  const photoUrl = `/api/construction-qa/photo-proxy?key=${encodeURIComponent(photo.storage_key)}&source=${photo.source}`;

  return (
    <div
      className="fixed inset-0 z-50 bg-black/95 flex flex-col"
      role="dialog"
      aria-label="Photo viewer"
    >
      {/* Top Bar */}
      <div className="flex items-center justify-between px-4 py-3 bg-black/50 border-b border-gray-800">
        <div className="text-sm text-gray-300">
          <span className="font-medium text-white">{photo.filename || 'Photo'}</span>
          <span className="ml-3 text-gray-500">
            {currentIndex + 1} / {photos.length}
          </span>
          {photo.vlm_confidence != null && (
            <span className={`ml-3 font-mono ${
              photo.vlm_confidence >= 0.8 ? 'text-green-400' :
              photo.vlm_confidence >= 0.6 ? 'text-yellow-400' : 'text-red-400'
            }`}>
              AI: {Math.round(photo.vlm_confidence * 100)}%
            </span>
          )}
        </div>

        <div className="flex items-center gap-2">
          {/* Zoom controls */}
          <button onClick={zoomOut} disabled={zoom <= MIN_ZOOM} className="p-2 text-gray-400 hover:text-white disabled:opacity-30 transition-colors" title="Zoom out (-)">
            <ZoomOut className="w-5 h-5" />
          </button>
          <span className="text-xs text-gray-400 w-12 text-center font-mono">{Math.round(zoom * 100)}%</span>
          <button onClick={zoomIn} disabled={zoom >= MAX_ZOOM} className="p-2 text-gray-400 hover:text-white disabled:opacity-30 transition-colors" title="Zoom in (+)">
            <ZoomIn className="w-5 h-5" />
          </button>
          <button onClick={resetView} className="p-2 text-gray-400 hover:text-white transition-colors" title="Reset zoom (0)">
            <RotateCcw className="w-4 h-4" />
          </button>

          <div className="w-px h-6 bg-gray-700 mx-1" />

          {/* Close */}
          <button onClick={onClose} className="p-2 text-gray-400 hover:text-white transition-colors" title="Close (Esc)">
            <X className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Photo Area */}
      <div
        ref={containerRef}
        className="flex-1 relative overflow-hidden flex items-center justify-center select-none"
        onClick={handleBackdropClick}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        style={{ cursor: zoom > 1 ? (isDragging ? 'grabbing' : 'grab') : 'default' }}
      >
        <img
          src={photoUrl}
          alt={photo.filename || 'Photo'}
          className="max-w-full max-h-full object-contain transition-transform duration-150"
          style={{
            transform: `scale(${zoom}) translate(${pan.x / zoom}px, ${pan.y / zoom}px)`,
          }}
          draggable={false}
        />

        {/* Prev arrow */}
        {currentIndex > 0 && (
          <button
            onClick={goPrev}
            className="absolute left-4 top-1/2 -translate-y-1/2 p-3 bg-black/60 rounded-full text-white hover:bg-black/80 transition-colors"
          >
            <ChevronLeft className="w-6 h-6" />
          </button>
        )}

        {/* Next arrow */}
        {currentIndex < photos.length - 1 && (
          <button
            onClick={goNext}
            className="absolute right-4 top-1/2 -translate-y-1/2 p-3 bg-black/60 rounded-full text-white hover:bg-black/80 transition-colors"
          >
            <ChevronRight className="w-6 h-6" />
          </button>
        )}
      </div>

      {/* Bottom Info Bar */}
      {photo.vlm_feedback && (
        <div className="px-4 py-2 bg-black/50 border-t border-gray-800">
          <p className="text-xs text-gray-400">{photo.vlm_feedback}</p>
        </div>
      )}
    </div>
  );
}

/**
 * POST /api/construction-qa/final-decision
 *
 * Phase 4: Record final QA decision (PASS / FAIL / REWORK_NEEDED)
 * Optionally triggers WhatsApp feedback in the same request.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth/middleware';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['POST']);
  }

  // Authenticated user is the decision-maker — not caller-supplied
  const authReq = req as AuthenticatedNextApiRequest;
  const decidedBy = authReq.user?.name || authReq.user?.email || 'unknown';

  try {
    const {
      reviewId,
      decision,
      reasonCodes = [],
      notes = '',
      sendFeedback = false,
    } = req.body;

    if (!reviewId || !decision) {
      return apiResponse.badRequest(res, 'reviewId and decision are required');
    }

    const validDecisions = ['PASS', 'FAIL', 'REWORK_NEEDED'];
    if (!validDecisions.includes(decision)) {
      return apiResponse.badRequest(res, `decision must be one of: ${validDecisions.join(', ')}`);
    }

    // Map decision to workflow status
    const statusMap: Record<string, string> = {
      PASS: 'approved',
      FAIL: 'rejected',
      REWORK_NEEDED: 'rework_needed',
    };
    const newStatus = statusMap[decision];

    // Require notes for FAIL and REWORK_NEEDED
    if ((decision === 'FAIL' || decision === 'REWORK_NEEDED') && !notes.trim()) {
      return apiResponse.badRequest(res, 'Notes are required for FAIL and REWORK_NEEDED decisions');
    }

    // Build the snapshot for rework tracking
    const currentReview = await sql`
      SELECT workflow_status, photo_count, vlm_confidence, qa_decision, qa_notes
      FROM construction_qa_reviews WHERE id = ${reviewId}::uuid LIMIT 1
    `;

    if (currentReview.length === 0) {
      return apiResponse.notFound(res, 'Review', reviewId);
    }

    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const row = currentReview[0]!;
    const snapshot = {
      captured_at: new Date().toISOString(),
      workflow_status: row.workflow_status,
      photo_count: Number(row.photo_count),
      vlm_confidence: row.vlm_confidence ? Number(row.vlm_confidence) : null,
      qa_decision: row.qa_decision,
      qa_notes: row.qa_notes,
      reason_codes: reasonCodes,
    };

    // Update the review
    await sql`
      UPDATE construction_qa_reviews
      SET workflow_status = ${newStatus},
          qa_decision = ${decision},
          qa_decision_at = NOW(),
          qa_decision_by = ${decidedBy},
          qa_reason_code = ${reasonCodes.length > 0 ? reasonCodes[0] : null},
          qa_notes = ${notes || null},
          rework_count = CASE WHEN ${decision} = 'REWORK_NEEDED' THEN rework_count + 1 ELSE rework_count END,
          resubmission_snapshots = COALESCE(resubmission_snapshots, '[]'::jsonb) || ${JSON.stringify(snapshot)}::jsonb,
          updated_at = NOW()
      WHERE id = ${reviewId}::uuid
    `;

    // Log activity
    await sql`
      INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
      VALUES (
        ${reviewId}::uuid,
        'decision_made',
        ${decidedBy},
        ${JSON.stringify({ decision, reason_codes: reasonCodes, notes })}::jsonb
      )
    `;

    // Send WhatsApp feedback if requested
    let waSent = false;
    let waError: string | undefined;

    if (sendFeedback && (decision === 'FAIL' || decision === 'REWORK_NEEDED')) {
      try {
        const reviewDetails = await sql`
          SELECT r.feature_id, r.discipline, r.wa_group_jid, r.wa_technician_phone,
                 p.project_name
          FROM construction_qa_reviews r
          JOIN projects p ON p.id = r.project_id
          WHERE r.id = ${reviewId}::uuid
        `;

        if (reviewDetails.length > 0) {
          // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
          const detail = reviewDetails[0]!;
          const message = buildFeedbackMessage(
            detail.project_name as string,
            detail.feature_id as string,
            detail.discipline as string,
            decision,
            reasonCodes,
            notes,
          );

          await sql`
            UPDATE construction_qa_reviews
            SET wa_feedback_sent_at = NOW(),
                wa_feedback_message = ${message}
            WHERE id = ${reviewId}::uuid
          `;

          waSent = true;
          log.info('WhatsApp feedback recorded', { module: 'construction-qa', reviewId });
        }
      } catch (waErr) {
        waError = (waErr as Error).message;
        log.error('WhatsApp feedback failed', { module: 'construction-qa', error: waError });
      }
    }

    return apiResponse.success(res, {
      reviewId,
      decision,
      waSent,
      waError,
    });
  } catch (error) {
    log.error('Final decision error', { module: 'construction-qa', error: (error as Error).message });
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

function buildFeedbackMessage(
  projectName: string,
  featureId: string,
  discipline: string,
  decision: string,
  reasonCodes: string[],
  notes: string,
): string {
  const emoji = decision === 'FAIL' ? '\u274c' : '\u26a0\ufe0f';
  const action = decision === 'FAIL' ? 'REJECTED' : 'REWORK NEEDED';

  let msg = `${emoji} *Construction QA — ${action}*\n\n`;
  msg += `*Project:* ${projectName}\n`;
  msg += `*Feature:* ${featureId}\n`;
  msg += `*Discipline:* ${discipline}\n\n`;

  if (reasonCodes.length > 0) {
    msg += `*Issues:*\n`;
    reasonCodes.forEach(code => {
      msg += `\u2022 ${code.replace(/_/g, ' ').toLowerCase()}\n`;
    });
    msg += '\n';
  }

  if (notes) {
    msg += `*Notes:* ${notes}\n\n`;
  }

  msg += `Please address the issues and resubmit photos.`;
  return msg;
}

/**
 * Construction QA Module — TypeScript Type Definitions
 *
 * Covers all three pre-activation construction disciplines:
 *   • Civil      — pole planting
 *   • Optical    — cable stringing
 *   • Splicing   — dome joint installation
 *
 * Database alignment: construction_qa_reviews, construction_qa_photos,
 *   construction_qa_activity, construction_qa_assignments (migrations 200–203).
 *
 * NLNH Confidence: HIGH — types derived directly from PRD sections 6, 7, and 14.
 */

// ============================================================================
// PRIMITIVE UNION TYPES (Enums as const-unions for type safety)
// ============================================================================

/** The construction discipline being quality-assured. */
export type Discipline = 'civil' | 'optical' | 'splicing';

/**
 * The physical infrastructure feature under review.
 * Maps 1:1 with database tables: poles, cable_spans, joints.
 */
export type FeatureType = 'pole' | 'cable_span' | 'joint';

/**
 * Workflow lifecycle for a construction QA review record.
 * Mirrors dr_photo_unified_reviews workflow in the Activate module.
 */
export type WorkflowStatus =
  | 'pending'
  | 'in_review'
  | 'approved'
  | 'rejected'
  | 'rework_needed'
  | 'escalated'
  | 'unidentified';

/** Processing state of the VLM validation pipeline for a review. */
export type VlmStatus = 'pending' | 'processing' | 'completed' | 'failed';

/** Photo storage origin — used for proxy routing and audit trail. */
export type PhotoSource = 'qfield' | 'sharepoint' | 'whatsapp' | 'upload';

/**
 * Formal QA decision on a feature, made in Phase 4 of the wizard.
 * REWORK_NEEDED sends the feature back to the field without failing it permanently.
 */
export type QaDecision = 'PASS' | 'FAIL' | 'REWORK_NEEDED';

/** Review queue priority for triage and assignment ordering. */
export type Priority = 'low' | 'normal' | 'high' | 'urgent';

/**
 * Manual override on a single photo (distinct from whole-feature QaDecision).
 * NULL means no manual review yet.
 */
export type PhotoManualStatus = 'approved' | 'rejected' | 'pending' | null;

/**
 * Activity event types logged to construction_qa_activity.
 * Provides a full audit trail of every state change.
 */
export type ActivityEventType =
  | 'photo_ingested'
  | 'vlm_started'
  | 'vlm_completed'
  | 'vlm_failed'
  | 'review_opened'
  | 'step_checked'
  | 'step_unchecked'
  | 'decision_made'
  | 'feedback_sent'
  | 'rework_requested'
  | 'resubmission_received'
  | 'assigned'
  | 'escalated'
  | 'comment_added';

// ============================================================================
// CHECKLIST STEP DEFINITIONS
// ============================================================================

/** A single step in a discipline-specific photo checklist. */
export interface ChecklistStep {
  /** Step number (1-based, matches civil_step_0N / optical_step_0N / splicing_step_0N columns). */
  step: number;
  /** Human-readable label shown in the wizard UI. */
  label: string;
  /**
   * Whether a photo for this step is always required.
   * When false the step is conditional (e.g., guy wires only if pole >9m).
   */
  required: boolean;
  /** Short description of what the VLM checks for this step. */
  vlmCheck: string;
  /** Optional field notes displayed as a tooltip in the wizard. */
  notes?: string;
}

/**
 * Eight-step checklist for civil (pole planting) discipline.
 * Aligned with Velocity Fibre Pole Install Capture Checklist.
 * Phase A: Pre-Install (1-5), Phase B: Installation (6-7), Phase C: Assets (8).
 */
