// Public API
// ============================================================================

export async function processPoleInstallPhoto(
  photoData: PhotoData,
  photoBase64: string,
  groupInfo: GroupInfo
): Promise<void> {
  const sql = getDb();

  try {
    // 1. VLM classify
    const classification = await classifyPolePhoto(photoBase64);

    // 2. Find or create session
    const session = await findOrCreateSession(
      groupInfo.groupJid, photoData.senderJid, photoData.senderName,
      groupInfo.projectId, classification.pole_number
    );

    // 3. Cross-ref pole
    let poleExistsInSow: boolean | null = null;
    let poleVerified = false;
    const effectivePole = classification.pole_number || session.pole_number;

    if (effectivePole) {
      const ref = await crossRefPole(effectivePole, groupInfo.projectId);
      poleExistsInSow = ref.exists;
      poleVerified = ref.exists;
    }

    // 4. Increment session
    const updated = await incrementStepCount(
      session.id, classification.step, classification.pole_number,
      poleVerified, poleExistsInSow
    );

    // 5. Update photo record
    await sql`
      UPDATE field_ops_wa_photos SET
        pole_install_session_id = ${session.id}::uuid,
        classified_step = ${classification.step},
        vlm_processed = TRUE,
        vlm_valid = ${classification.quality_ok},
        vlm_confidence = ${classification.confidence},
        vlm_feedback = ${classification.feedback},
        vlm_processed_at = NOW()
      WHERE id = ${photoData.photoId}::uuid
    `;

    // 6. Check completion
    const complete = isSessionComplete(updated);
    if (complete) {
      await markComplete(updated.id);
      // Fire-and-forget: link to construction QA review
      linkSessionToQaReview(updated.id).catch((err) =>
        logger.error('QA review link failed', {
          error: err instanceof Error ? err.message : String(err),
          sessionId: updated.id,
        })
      );
    }

    // 7. Build and send ACK
    const ackMessage = buildAckMessage(
      classification.step, updated, classification.quality_ok,
      classification.issues, classification.feedback, poleExistsInSow
    );
    await sendAckToGroup(groupInfo.groupJid, photoData.senderJid, ackMessage);

    logger.info('Pole install photo processed', {
      sessionId: session.id, step: classification.step,
      totalPhotos: updated.total_photos, complete,
    });
  } catch (err) {
    logger.error('processPoleInstallPhoto failed', {
      error: err instanceof Error ? err.message : String(err),
      photoId: photoData.photoId, groupJid: groupInfo.groupJid,
    });
  }
}

export async function handlePoleTextMessage(
  messageText: string,
  senderJid: string,
  senderName: string,
  groupJid: string,
  projectId: string,
  _projectName: string
): Promise<void> {
  const poleNumber = extractPoleFromText(messageText);
  if (!poleNumber) return;

  try {
    const session = await findOrCreateSession(
      groupJid, senderJid, senderName, projectId, poleNumber
    );

    if (!session.pole_number) {
      const sql = getDb();
      await sql`
        UPDATE pole_install_sessions
        SET pole_number = ${poleNumber}, updated_at = NOW()
        WHERE id = ${session.id}::uuid
      `;
    }

    const ref = await crossRefPole(poleNumber, projectId);
    const sowTag = ref.exists ? '✓ Found in SOW' : '✗ Not in SOW';
    await sendAckToGroup(groupJid, senderJid, `📍 Pole ${poleNumber} registered ${sowTag} — send photos now`);

    logger.info('Pole text declaration processed', {
      poleNumber, sessionId: session.id, existsInSow: ref.exists,
    });
  } catch (err) {
    logger.error('handlePoleTextMessage failed', {
      error: err instanceof Error ? err.message : String(err),
      poleNumber, groupJid,
    });
  }
}

/**
 * EXFO Exchange Sync API
 *
 * POST /api/exfo/sync — Trigger sync for one or all workspaces
 *   Body: { workspaceId?, full?, fetchDetails? }
 *   Auth: session cookie OR x-cron-secret header (for cron jobs)
 *
 * GET /api/exfo/sync — Get sync history (session auth only)
 *   ?workspaceId=xxx&limit=20
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth/middleware';
import { createLogger } from '@/lib/logger';
import { syncWorkspace, syncAllWorkspaces, getSyncConfigs } from '@/services/exfo';

const logger = createLogger('api:exfo:sync');
const sql = neon(process.env.DATABASE_URL!);

/**
 * Check if request is authenticated via cron secret header.
 */
function hasCronSecret(req: NextApiRequest): boolean {
  const cronSecret = req.headers['x-cron-secret'];
  return !!process.env.CRON_SECRET && cronSecret === process.env.CRON_SECRET;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'POST') {
    return handleSync(req, res);
  }

  if (req.method === 'GET') {
    return handleGetHistory(req, res);
  }

  return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['GET', 'POST']);
}

/**
 * POST handler — accepts both session auth (via withAuth wrapper) and cron secret.
 * The cron secret path is checked in the exported default below.
 */

async function handleSync(req: NextApiRequest, res: NextApiResponse) {
  try {
    const { workspaceId, full, fetchDetails } = req.body || {};

    if (workspaceId) {
      const configs = await getSyncConfigs();
      const config = configs.find(c => c.workspace_id === workspaceId);

      if (!config) {
        return apiResponse.notFound(res, 'EXFO workspace config', workspaceId);
      }

      const result = await syncWorkspace(config, { full, fetchDetails });
      return apiResponse.success(res, result);
    }

    const results = await syncAllWorkspaces({ full, fetchDetails });
    return apiResponse.success(res, results);
  } catch (err) {
    return apiResponse.internalError(res, err);
  }
}

async function handleGetHistory(req: NextApiRequest, res: NextApiResponse) {
  try {
    const workspaceId = req.query.workspaceId as string || '';
    const limit = Math.min(100, Math.max(1, parseInt(req.query.limit as string || '20', 10)));

    let rows;
    if (workspaceId) {
      rows = await sql`
        SELECT * FROM exfo_sync_history
        WHERE workspace_id = ${workspaceId}
        ORDER BY started_at DESC
        LIMIT ${limit}
      `;
    } else {
      rows = await sql`
        SELECT * FROM exfo_sync_history
        ORDER BY started_at DESC
        LIMIT ${limit}
      `;
    }

    return apiResponse.success(res, { history: rows });
  } catch (err) {
    return apiResponse.internalError(res, err);
  }
}

/**
 * Allow POST with cron secret header to bypass session auth.
 * GET (history) still requires session auth.
 */
async function authGate(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'POST' && hasCronSecret(req)) {
    logger.info('EXFO sync triggered via cron secret');
    return handler(req, res);
  }

  // Fall through to session auth for all other requests
  return withAuth(handler)(req, res);
}

export default authGate;

/**
 * Pole Install Completion Service
 *
 * When a pole_install_session reaches all required photos, this service:
 * 1. Creates a construction_qa_reviews record
 * 2. Sets civil step flags based on classified photos
 * 3. Links field_ops_wa_photos to the QA review
 *
 * @module field-ops/services/poleInstallCompletionService
 */

import { neon } from '@neondatabase/serverless';
import { createLogger } from '@/lib/logger';

const logger = createLogger('poleInstallCompletionService');

function getDb() {
  if (!process.env.DATABASE_URL) throw new Error('DATABASE_URL not set');
  return neon(process.env.DATABASE_URL);
}

interface CompletedSession {
  id: string;
  project_id: string;
  pole_number: string | null;
  wa_group_jid: string;
  sender_jid: string | null;
  before_count: number;
  during_count: number;
  depth_count: number;
  endplate_count: number;
  compaction_count: number;
  level_count: number;
  stumping_count: number;
  housekeeping_count: number;
  signature_count: number;
  total_photos: number;
}

/**
 * Create a construction_qa_reviews record from a completed pole install session
 * and link the associated photos.
 */
export async function linkSessionToQaReview(sessionId: string): Promise<string | null> {
  const sql = getDb();

  try {
    // Fetch session
    const sessions = await sql`
      SELECT * FROM pole_install_sessions WHERE id = ${sessionId}::uuid
    `;
    if (sessions.length === 0) {
      logger.error('Session not found for QA link', { sessionId });
      return null;
    }
    const session = sessions[0] as unknown as CompletedSession;

    // Check if QA review already exists for this pole + project
    const existing = await sql`
      SELECT id FROM construction_qa_reviews
      WHERE project_id = ${session.project_id}::uuid
        AND feature_id = ${session.pole_number}
        AND discipline = 'civil'
      LIMIT 1
    `;

    let qaReviewId: string;

    const existingReview = existing[0];
    if (existingReview) {
      qaReviewId = String(existingReview.id);
    } else {
      // Create new QA review
      const inserted = await sql`
        INSERT INTO construction_qa_reviews (
          project_id, discipline, feature_type, feature_id,
          photo_count, photo_sources, wa_group_jid, wa_technician_phone,
          workflow_status,
          civil_step_01_before_photo,
          civil_step_02_during_photo,
          civil_step_03_depth_photo,
          civil_step_04_end_plates,
          civil_step_05_compaction,
          civil_step_06_level_check,
          civil_step_07_after_photo,
          civil_step_08_signature
        ) VALUES (
          ${session.project_id}::uuid, 'civil', 'pole', ${session.pole_number},
          ${session.total_photos}, ARRAY['whatsapp']::text[], ${session.wa_group_jid},
          ${session.sender_jid},
          'pending',
          ${session.before_count > 0},
          ${session.during_count > 0},
          ${session.depth_count > 0},
          ${session.endplate_count > 0},
          ${session.compaction_count > 0},
          ${session.level_count > 0},
          ${session.stumping_count > 0},
          ${session.signature_count > 0}
        )
        RETURNING id
      `;
      const newReview = inserted[0];
      qaReviewId = String(newReview?.id ?? '');
    }

    // Link session to QA review
    await sql`
      UPDATE pole_install_sessions
      SET construction_qa_review_id = ${qaReviewId}::uuid, updated_at = NOW()
      WHERE id = ${sessionId}::uuid
    `;

    // Link photos to QA review
    await sql`
      UPDATE field_ops_wa_photos
      SET construction_qa_review_id = ${qaReviewId}::uuid
      WHERE pole_install_session_id = ${sessionId}::uuid
    `;

    logger.info('Session linked to QA review', { sessionId, qaReviewId });
    return qaReviewId;
  } catch (err) {
    logger.error('Failed to link session to QA review', {
      error: err instanceof Error ? err.message : String(err),
      sessionId,
    });
    return null;
  }
}

/**
 * Field Ops Photo Processing Service
 *
 * Handles downloading WhatsApp construction photos from the bridge and staging
 * them for Firebase upload. Processes photos from field_ops_wa_photos table
 * with pending upload_status.
 *
 * Flow:
 * 1. Query pending photos from field_ops_wa_photos
 * 2. Request download from WhatsApp bridge /api/download
 * 3. Stage file locally and record intended Firebase storage path
 * 4. Update status to 'uploaded' with storage_key
 *
 * @module field-ops/services/fieldOpsPhotoService
 */

import { neon } from '@neondatabase/serverless';
import { createLogger } from '@/lib/logger';
import fs from 'fs';

const logger = createLogger('fieldOpsPhotoService');

// ============================================================================
// Configuration
// ============================================================================

const WA_BRIDGE_DOWNLOAD_URL =
  process.env.WA_BRIDGE_URL || 'http://72.61.197.178:8083/api/download';

// ============================================================================
// Database Connection
// ============================================================================

function getDb() {
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    throw new Error('DATABASE_URL environment variable is not set');
  }
  return neon(databaseUrl);
}

// ============================================================================
// Types
// ============================================================================

interface PendingPhoto {
  id: string;
  message_id: string;
  wa_media_id: string;
  wa_group_jid: string;
  group_type: string;
  project: string;
  sender_name: string;
  message_timestamp: string;
  mime_type: string;
  wa_message_id: string;
}

interface DownloadResult {
  success: boolean;
  filename?: string;
  path?: string;
  error?: string;
}

interface FirebaseStageResult {
  success: boolean;
  storageKey?: string;
  error?: string;
}

// ============================================================================
// WhatsApp Bridge Media Download
// ============================================================================

/**
 * Download media from WhatsApp bridge
 */
async function downloadFromBridge(
  messageId: string,
  chatJid: string
): Promise<DownloadResult> {
  try {
    const response = await fetch(WA_BRIDGE_DOWNLOAD_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        message_id: messageId,
        chat_jid: chatJid,
      }),
    });

    const result = await response.json();

    if (result.success && result.path) {
      return {
        success: true,
        filename: result.filename,
        path: result.path,
      };
    }

    return {
      success: false,
      error: result.message || 'Unknown download error',
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Download failed',
    };
  }
}

// ============================================================================
// Firebase Storage Staging
// ============================================================================

/**
 * Stage photo for Firebase upload.
 * Records the intended Firebase storage path; the file is already local from the bridge.
 * Actual Firebase upload runs in a background job when credentials are configured.
 */
async function stageForFirebase(
  localPath: string,
  storagePath: string
): Promise<FirebaseStageResult> {
  try {
    if (!fs.existsSync(localPath)) {
      return { success: false, error: `Local file not found: ${localPath}` };
    }

    logger.info('Photo staged for Firebase upload', { localPath, storagePath });
    return { success: true, storageKey: storagePath };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Staging failed',
    };
  }
}

// ============================================================================
// Photo Processing
// ============================================================================

/**
 * Get pending photos that need downloading and uploading
 */
export async function getPendingPhotos(limit = 10): Promise<PendingPhoto[]> {
  const sql = getDb();

  const result = await sql`
    SELECT
      p.id,
      p.message_id,
      p.wa_media_id,
      p.wa_group_jid,
      p.group_type,
      p.project,
      p.sender_name,
      p.message_timestamp,
      p.mime_type,
      m.wa_message_id
    FROM field_ops_wa_photos p
    JOIN field_ops_wa_messages m ON p.message_id = m.id
    WHERE p.upload_status = 'pending'
    ORDER BY p.created_at ASC
    LIMIT ${limit}
  `;

  return result as unknown as PendingPhoto[];
}

/**
 * Process a single pending photo: download from bridge + stage for Firebase
 */
export async function processPhoto(
  photo: PendingPhoto
): Promise<{ success: boolean; error?: string }> {
  const sql = getDb();

  // Mark as uploading
  await sql`
    UPDATE field_ops_wa_photos
    SET upload_status = 'uploading', updated_at = NOW()
    WHERE id = ${photo.id}
  `;

  // Step 1: Download from WhatsApp bridge
  logger.info('Downloading photo from bridge', {
    photoId: photo.id,
    messageId: photo.wa_message_id,
  });

  const download = await downloadFromBridge(photo.wa_message_id, photo.wa_group_jid);

  if (!download.success || !download.path) {
    await sql`
      UPDATE field_ops_wa_photos
      SET upload_status = 'failed', upload_error = ${download.error || null}, updated_at = NOW()
      WHERE id = ${photo.id}
    `;
    return { success: false, error: download.error };
  }

  // Step 2: Stage for Firebase
  const date = new Date(photo.message_timestamp).toISOString().split('T')[0];
  const filename = download.filename || `photo_${photo.id}.jpg`;
  const storagePath = `construction-qa/${photo.project}/${date}/${filename}`;

  const stage = await stageForFirebase(download.path, storagePath);

  if (!stage.success) {
    await sql`
      UPDATE field_ops_wa_photos
      SET upload_status = 'failed', upload_error = ${stage.error || null}, updated_at = NOW()
      WHERE id = ${photo.id}
    `;
    return { success: false, error: stage.error };
  }

  // Step 3: Update to uploaded with storage key and local path
  await sql`
    UPDATE field_ops_wa_photos
    SET
      upload_status = 'uploaded',
      storage_key = ${stage.storageKey || null},
      local_path = ${download.path},
      uploaded_at = NOW(),
      updated_at = NOW()
    WHERE id = ${photo.id}
  `;

  logger.info('Photo staged successfully', {
    photoId: photo.id,
    storageKey: stage.storageKey,
  });

  return { success: true };
}

/**
 * Batch process pending photos (download + stage)
 */
export async function processPendingPhotos(limit = 10): Promise<{
  processed: number;
  succeeded: number;
  failed: number;
  errors: string[];
}> {
  const pendingPhotos = await getPendingPhotos(limit);

  const results = {
    processed: 0,
    succeeded: 0,
    failed: 0,
    errors: [] as string[],
  };

  for (const photo of pendingPhotos) {
    results.processed++;

    try {
      const result = await processPhoto(photo);

      if (result.success) {
        results.succeeded++;
      } else {
        results.failed++;
        results.errors.push(`Photo ${photo.id}: ${result.error}`);
      }
    } catch (error) {
      results.failed++;
      results.errors.push(
        `Photo ${photo.id}: ${error instanceof Error ? error.message : 'Unknown error'}`
      );
    }
  }

  logger.info('Batch photo processing complete', {
    processed: results.processed,
    succeeded: results.succeeded,
    failed: results.failed,
  });

  return results;
}

/**
 * Field Ops Photo Processing Endpoint
 *
 * POST /api/field-ops/process-photos
 *   - Validates x-cron-secret header
 *   - Runs photo download + staging batch (fieldOpsPhotoService)
 *   - Runs VLM validation + cross-reference batch (fieldOpsVlmService)
 *   - Returns combined results
 *
 * Intended for cron invocation every few minutes.
 *
 * @module api/field-ops/process-photos
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { createLogger } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { processPendingPhotos } from '@/modules/field-ops/services/fieldOpsPhotoService';
import { validatePendingPhotos } from '@/modules/field-ops/services/fieldOpsVlmService';

const logger = createLogger('api:field-ops:process-photos');

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method !== 'POST') {
    apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
    return;
  }

  // Validate cron secret
  const cronSecret = req.headers['x-cron-secret'];
  if (!process.env.CRON_SECRET || cronSecret !== process.env.CRON_SECRET) {
    apiResponse.unauthorized(res, 'Invalid or missing cron secret');
    return;
  }

  const { photoLimit = 10, vlmLimit = 5 } = req.body || {};

  logger.info('Starting field-ops photo processing', { photoLimit, vlmLimit });

  try {
    // Phase 1: Download + stage photos from WhatsApp bridge
    const photoResults = await processPendingPhotos(Number(photoLimit));

    logger.info('Photo download batch complete', {
      processed: photoResults.processed,
      succeeded: photoResults.succeeded,
      failed: photoResults.failed,
    });

    // Phase 2: VLM validation + project cross-reference
    const vlmResults = await validatePendingPhotos(Number(vlmLimit));

    logger.info('VLM validation batch complete', {
      processed: vlmResults.processed,
      succeeded: vlmResults.succeeded,
      failed: vlmResults.failed,
    });

    apiResponse.success(res, {
      photos: photoResults,
      vlm: vlmResults,
    });
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    logger.error('Field-ops photo processing failed', { error: errorMessage });
    apiResponse.internalError(res, error, 'Photo processing pipeline failed');
  }
}

/**
 * Field Ops WhatsApp Message Endpoint
 *
 * Receives incoming WhatsApp messages from the VPS bridge for civil/optical
 * field operations groups. Stores messages and creates pending photo records.
 *
 * POST /api/field-ops/wa-message
 * Auth: x-bridge-secret header
 *
 * @module api/field-ops/wa-message
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { createLogger } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import {
  processPoleInstallPhoto,
  handlePoleTextMessage,
  type PhotoData,
  type GroupInfo,
} from '@/modules/field-ops/services/poleInstallAckService';

const logger = createLogger('api:field-ops:wa-message');

interface IncomingFieldOpsMessage {
  group_jid: string;
  sender_jid: string;
  sender_name?: string;
  message_text?: string;
  message_id: string;
  timestamp: string;
  has_media?: boolean;
  media_type?: string;
  media_count?: number;
  photo_base64?: string;
  photo_filename?: string;
}

interface GroupLookupResult {
  group_type: string;
  project_name: string | null;
  project_id: string | null;
}

interface MessageInsertResult {
  id: string;
}

// neon() tagged-template returns Record<string,any>[] — these helpers cast safely
function toGroupResult(row: Record<string, unknown>): GroupLookupResult {
  return {
    group_type: String(row['group_type'] ?? ''),
    project_name: row['project_name'] != null ? String(row['project_name']) : null,
    project_id: row['project_id'] != null ? String(row['project_id']) : null,
  };
}

function toMessageResult(row: Record<string, unknown>): MessageInsertResult {
  return { id: String(row['id'] ?? '') };
}

async function handler(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const bridgeSecret = process.env.WA_BRIDGE_SECRET;
  if (!bridgeSecret) {
    logger.error('WA_BRIDGE_SECRET env var not set');
    return apiResponse.internalError(res, new Error('Server configuration error'));
  }

  const headerSecret = req.headers['x-bridge-secret'];
  if (headerSecret !== bridgeSecret) {
    logger.warn('Invalid or missing x-bridge-secret header');
    return apiResponse.unauthorized(res, 'Invalid bridge secret');
  }

  const body = req.body as IncomingFieldOpsMessage;

  if (!body.message_id) {
    return apiResponse.badRequest(res, 'Missing required field: message_id');
  }
  if (!body.group_jid) {
    return apiResponse.badRequest(res, 'Missing required field: group_jid');
  }
  if (!body.sender_jid) {
    return apiResponse.badRequest(res, 'Missing required field: sender_jid');
  }
  if (!body.timestamp) {
    return apiResponse.badRequest(res, 'Missing required field: timestamp');
  }

  const sql = neon(process.env.DATABASE_URL!);

  try {
    // Look up group in wa_monitored_groups to get group_type and project
    const groupRows = (await sql`
      SELECT group_type, project_name, project_id
      FROM wa_monitored_groups
      WHERE group_jid = ${body.group_jid}
        AND is_active = TRUE
    `).map(toGroupResult);

    if (groupRows.length === 0) {
      logger.warn('Message from unknown or inactive group', { group_jid: body.group_jid });
      return apiResponse.badRequest(res, `Unknown or inactive group: ${body.group_jid}`);
    }

    const { group_type, project_name, project_id } = groupRows[0]!

    // Determine message timestamp from bridge payload
    const messageTimestamp = new Date(
      typeof body.timestamp === 'number' ? body.timestamp * 1000 : body.timestamp
    ).toISOString();

    // Insert the message (idempotent via ON CONFLICT DO NOTHING)
    const insertedRows = (await sql`
      INSERT INTO field_ops_wa_messages (
        wa_message_id,
        wa_group_jid,
        group_type,
        sender_jid,
        sender_name,
        message_text,
        message_timestamp,
        project,
        has_media,
        media_type,
        media_count
      ) VALUES (
        ${body.message_id},
        ${body.group_jid},
        ${group_type},
        ${body.sender_jid},
        ${body.sender_name ?? null},
        ${body.message_text ?? null},
        ${messageTimestamp},
        ${project_name ?? null},
        ${body.has_media ?? false},
        ${body.media_type ?? null},
        ${body.media_count ?? 0}
      )
      ON CONFLICT (wa_message_id) DO NOTHING
      RETURNING id
    `).map(toMessageResult);

    // If message was a duplicate, return early
    if (insertedRows.length === 0) {
      logger.info('Duplicate message ignored', { message_id: body.message_id });
      return apiResponse.success(res, { message_id: body.message_id, duplicate: true });
    }

    const messageDbId = insertedRows[0]!.id;

    // If the message has images, create pending photo records (one per image)
    const photoCount = body.media_count ?? 0;
    if (body.has_media && body.media_type === 'image' && photoCount > 0) {
      const photoInserts = Array.from({ length: photoCount }, () =>
        sql`
          INSERT INTO field_ops_wa_photos (
            message_id,
            wa_group_jid,
            group_type,
            sender_jid,
            sender_name,
            message_timestamp,
            project,
            upload_status,
            vlm_processed
          ) VALUES (
            ${messageDbId},
            ${body.group_jid},
            ${group_type},
            ${body.sender_jid},
            ${body.sender_name ?? null},
            ${messageTimestamp},
            ${project_name ?? null},
            'pending',
            FALSE
          )
        `
      );

      await Promise.all(photoInserts);

      logger.info('Photo records created', {
        message_id: body.message_id,
        photos_created: photoCount,
        project: project_name,
      });

      // Fire-and-forget: real-time pole install ACK pipeline
      if (body.photo_base64 && project_id && group_type === 'civil') {
        const photoData: PhotoData = {
          photoId: messageDbId, // Use message DB ID as photo reference
          senderJid: body.sender_jid,
          senderName: body.sender_name ?? 'Unknown',
          messageTimestamp: messageTimestamp,
        };
        const groupInfo: GroupInfo = {
          groupJid: body.group_jid,
          projectId: project_id,
          projectName: project_name ?? '',
        };
        processPoleInstallPhoto(photoData, body.photo_base64, groupInfo).catch((err) =>
          logger.error('Pole install ACK pipeline failed', {
            error: err instanceof Error ? err.message : String(err),
            message_id: body.message_id,
          })
        );
      }
    }

    // Fire-and-forget: check text messages for pole number declarations
    if (!body.has_media && body.message_text && project_id && group_type === 'civil') {
      handlePoleTextMessage(
        body.message_text, body.sender_jid, body.sender_name ?? 'Unknown',
        body.group_jid, project_id, project_name ?? ''
      ).catch((err) =>
        logger.error('Pole text message handler failed', {
          error: err instanceof Error ? err.message : String(err),
          message_id: body.message_id,
        })
      );
    }

    logger.info('Field ops WA message stored', {
      message_id: body.message_id,
      group_type,
      project: project_name,
      has_media: body.has_media,
    });

    return apiResponse.success(res, {
      message_id: body.message_id,
      db_id: messageDbId,
      group_type,
      project: project_name,
      photos_created: body.has_media && body.media_type === 'image' ? photoCount : 0,
    });
  } catch (error) {
    logger.error('Failed to store field ops WA message', {
      error: error instanceof Error ? error.message : String(error),
      message_id: body.message_id,
    });
    return apiResponse.internalError(res, error);
  }
}

