function VerdictBadge({ verdict }: { verdict: string | null }) {
  if (verdict === 'Pass') {
    return (
      <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium bg-green-500/10 text-green-400">
        <CheckCircle className="w-3 h-3" /> Pass
      </span>
    );
  }
  if (verdict === 'Fail') {
    return (
      <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium bg-red-500/10 text-red-400">
        <XCircle className="w-3 h-3" /> Fail
      </span>
    );
  }
  return (
    <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-500/10 text-gray-400">
      —
    </span>
  );
}

/**
 * API Route: /api/projects/[projectId]/pon-stages
 *
 * Returns PON stage tracker data: per-PON build pipeline progress
 * grouped by zone with 6 stages per PON.
 *
 * Method: GET
 * Query: ?zone=N (optional filter)
 *
 * Response: PonStagesResponse
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import pool from '@/lib/db';
import { log } from '@/lib/logger';
import { withAuth } from '@/lib/auth';
import type {
  PonStagesResponse,
  PonStageRow,
  PonStageData,
  ZoneStageNode,
  BuildStage,
  OverallStage,
} from '@/types/pon-stages.types';
import { BUILD_STAGES } from '@/types/pon-stages.types';

interface RawRow {
  zone_no: number;
  pon_no: number;
  permissions_total: string;
  permissions_approved: string;
  permissions_first_date: string | null;
  permissions_last_date: string | null;
  poles_total: string;
  poles_planted: string;
  poles_first_date: string | null;
  poles_last_date: string | null;
  cwc_total: string;
  cwc_complete: string;
  cwc_first_date: string | null;
  cwc_last_date: string | null;
  optical_total: string;
  optical_complete: string;
  optical_first_date: string | null;
  optical_last_date: string | null;
  atp_total: string;
  atp_passed: string;
  atp_first_date: string | null;
  atp_last_date: string | null;
  activation_total: string;
  activation_complete: string;
  activation_first_date: string | null;
  activation_last_date: string | null;
  overall_stage: string;
  last_synced_at: string;
}

function makeStageData(total: number, complete: number, firstDate: string | null, lastDate: string | null): PonStageData {
  return {
    total,
    complete,
    pct: total > 0 ? Math.round((complete / total) * 10000) / 100 : 0,
    first_date: firstDate,
    last_date: lastDate,
  };
}

function aggregateStages(pons: PonStageRow[]): Record<BuildStage, PonStageData> {
  const result = {} as Record<BuildStage, PonStageData>;
  for (const stage of BUILD_STAGES) {
    let totalSum = 0;
    let completeSum = 0;
    let firstDate: string | null = null;
    let lastDate: string | null = null;

    for (const pon of pons) {
      const data = pon[stage];
      totalSum += data.total;
      completeSum += data.complete;
      if (data.first_date && (!firstDate || data.first_date < firstDate)) firstDate = data.first_date;
      if (data.last_date && (!lastDate || data.last_date > lastDate)) lastDate = data.last_date;
    }

    result[stage] = makeStageData(totalSum, completeSum, firstDate, lastDate);
  }
  return result;
}

async function handler(
  req: NextApiRequest,
  res: NextApiResponse<PonStagesResponse | { error: string }>
) {
  if (req.method !== 'GET') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const { projectId, zone } = req.query;
  const projectIdStr = Array.isArray(projectId) ? projectId[0] : projectId;
  const zoneFilter = zone ? Number(Array.isArray(zone) ? zone[0] : zone) : null;

  if (!projectIdStr) {
    return res.status(400).json({ error: 'Missing projectId' });
  }

  try {
    const client = await pool.connect();
    try {
      // Get project name
      const projectResult = await client.query<{ project_name: string }>(
        'SELECT project_name FROM projects WHERE id = $1',
        [projectIdStr]
      );

      if (projectResult.rows.length === 0) {
        return res.status(404).json({ error: 'Project not found' });
      }

      const projectName = projectResult.rows[0]!.project_name;

      // Fetch PON stage data
      let query = `
        SELECT zone_no, pon_no,
          permissions_total::text, permissions_approved::text,
          permissions_first_date::text, permissions_last_date::text,
          poles_total::text, poles_planted::text,
          poles_first_date::text, poles_last_date::text,
          cwc_total::text, cwc_complete::text,
          cwc_first_date::text, cwc_last_date::text,
          optical_total::text, optical_complete::text,
          optical_first_date::text, optical_last_date::text,
          atp_total::text, atp_passed::text,
          atp_first_date::text, atp_last_date::text,
          activation_total::text, activation_complete::text,
          activation_first_date::text, activation_last_date::text,
          overall_stage,
          last_synced_at::text
        FROM pon_stage_tracking
        WHERE project_id = $1
      `;
      const params: (string | number)[] = [projectIdStr];

      if (zoneFilter !== null) {
        query += ' AND zone_no = $2';
        params.push(zoneFilter);
      }

      query += ' ORDER BY zone_no, pon_no';

      const result = await client.query<RawRow>(query, params);

      // Build PON rows
      const flatRows: PonStageRow[] = result.rows.map(row => ({
        zone_no: row.zone_no,
        pon_no: row.pon_no,
        permissions: makeStageData(Number(row.permissions_total), Number(row.permissions_approved), row.permissions_first_date, row.permissions_last_date),
        poles: makeStageData(Number(row.poles_total), Number(row.poles_planted), row.poles_first_date, row.poles_last_date),
        cwc: makeStageData(Number(row.cwc_total), Number(row.cwc_complete), row.cwc_first_date, row.cwc_last_date),
        optical: makeStageData(Number(row.optical_total), Number(row.optical_complete), row.optical_first_date, row.optical_last_date),
        atp: makeStageData(Number(row.atp_total), Number(row.atp_passed), row.atp_first_date, row.atp_last_date),
        activation: makeStageData(Number(row.activation_total), Number(row.activation_complete), row.activation_first_date, row.activation_last_date),
        overall_stage: row.overall_stage as OverallStage,
        last_synced_at: row.last_synced_at,
      }));

      // Build zone hierarchy
      const zoneMap = new Map<number, PonStageRow[]>();
      for (const row of flatRows) {
        const existing = zoneMap.get(row.zone_no);
        if (existing) {
          existing.push(row);
        } else {
          zoneMap.set(row.zone_no, [row]);
        }
      }

      const hierarchy: ZoneStageNode[] = [];
      for (const [zoneNo, pons] of zoneMap) {
        hierarchy.push({
          zone_no: zoneNo,
          zone_name: `Zone ${zoneNo}`,
          pons,
          stages: aggregateStages(pons),
        });
      }
      hierarchy.sort((a, b) => a.zone_no - b.zone_no);

      // Build summary
      const allStages = aggregateStages(flatRows);
      let lastSynced: string | null = null;
      for (const row of flatRows) {
        if (row.last_synced_at && (!lastSynced || row.last_synced_at > lastSynced)) {
          lastSynced = row.last_synced_at;
        }
      }

      const response: PonStagesResponse = {
        project_id: projectIdStr,
        project_name: projectName,
        summary: {
          total_pons: flatRows.length,
          stages: allStages,
          last_synced: lastSynced,
        },
        hierarchy,
        flat: flatRows,
      };

      log.info('PON stages fetched', {
        projectId: projectIdStr,
        totalPons: flatRows.length,
        zones: hierarchy.length,
      }, 'PonStages');

      return res.status(200).json(response);
    } finally {
      client.release();
    }
  } catch (error) {
    log.error('Failed to fetch PON stages', { error, projectId: projectIdStr }, 'PonStages');
    return res.status(500).json({
      error: error instanceof Error ? error.message : 'Internal server error',
    });
  }
}

export default withAuth(handler);

/**
 * EXFO Test Results API
 *
 * GET /api/exfo/results — List synced test results with filters
 *   ?projectId=xxx&testType=olts&verdict=Pass&search=xxx
 *   &page=1&pageSize=50&workspaceId=xxx&assetId=xxx
 *
 * GET /api/exfo/results?action=stats — Aggregate stats
 * GET /api/exfo/results?action=equipment — Equipment summary
 * GET /api/exfo/results?action=projects — Projects with result counts
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth/middleware';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['GET']);
  }

  try {
    const action = req.query.action as string || '';

    if (action === 'stats') return handleStats(req, res);
    if (action === 'equipment') return handleEquipment(req, res);
    if (action === 'projects') return handleProjects(res);

    return handleList(req, res);
  } catch (err) {
    return apiResponse.internalError(res, err);
  }
}

async function handleList(req: NextApiRequest, res: NextApiResponse) {
  const projectId = (req.query.projectId as string) || null;
  const testType = (req.query.testType as string) || null;
  const verdict = (req.query.verdict as string) || null;
  const search = (req.query.search as string) || null;
  const workspaceId = (req.query.workspaceId as string) || null;
  const assetId = (req.query.assetId as string) || null;
  const page = Math.max(1, parseInt(req.query.page as string || '1', 10));
  const pageSize = Math.min(200, Math.max(1, parseInt(req.query.pageSize as string || '50', 10)));
  const offset = (page - 1) * pageSize;
  const searchPattern = search ? `%${search}%` : null;

  // Use null-check pattern: (${val} IS NULL OR column = ${val})
  // When val is null, IS NULL is TRUE so the clause is skipped (no filter)
  // When val has a value, IS NULL is FALSE so the equality check runs
  const rows = await sql`
    SELECT
      r.id, r.exfo_result_id, r.exfo_workspace_id,
      r.test_type, r.test_name, r.job_name,
      r.global_verdict, r.test_date_time, r.server_updated_date,
      r.parsed_project, r.parsed_pole, r.parsed_cabinet,
      r.parsed_port, r.parsed_link, r.parsed_fiber,
      r.unit_a_serial, r.unit_a_model,
      r.unit_b_serial, r.unit_b_model,
      r.platform_serial, r.platform_model,
      r.company_name, r.customer_name, r.operator_a,
      r.cable_id, r.fiber_id, r.location_a, r.location_b,
      r.project_id, r.asset_id, r.attachments_count,
      r.synced_at, r.created_at,
      p.project_name,
      a.name AS asset_name
    FROM exfo_test_results r
    LEFT JOIN projects p ON p.id = r.project_id
    LEFT JOIN assets a ON a.id = r.asset_id
    WHERE (${projectId}::UUID IS NULL OR r.project_id = ${projectId}::UUID)
      AND (${testType}::TEXT IS NULL OR r.test_type = ${testType})
      AND (${verdict}::TEXT IS NULL OR r.global_verdict = ${verdict})
      AND (${workspaceId}::TEXT IS NULL OR r.exfo_workspace_id = ${workspaceId})
      AND (${assetId}::UUID IS NULL OR r.asset_id = ${assetId}::UUID)
      AND (${searchPattern}::TEXT IS NULL OR (
        r.test_name ILIKE ${searchPattern}
        OR r.job_name ILIKE ${searchPattern}
        OR r.cable_id ILIKE ${searchPattern}
        OR r.operator_a ILIKE ${searchPattern}
        OR r.unit_a_serial ILIKE ${searchPattern}
      ))
    ORDER BY r.test_date_time DESC NULLS LAST
    LIMIT ${pageSize} OFFSET ${offset}
  `;

  const countRows = await sql`
    SELECT COUNT(*) as total FROM exfo_test_results r
    WHERE (${projectId}::UUID IS NULL OR r.project_id = ${projectId}::UUID)
      AND (${testType}::TEXT IS NULL OR r.test_type = ${testType})
      AND (${verdict}::TEXT IS NULL OR r.global_verdict = ${verdict})
      AND (${workspaceId}::TEXT IS NULL OR r.exfo_workspace_id = ${workspaceId})
      AND (${assetId}::UUID IS NULL OR r.asset_id = ${assetId}::UUID)
      AND (${searchPattern}::TEXT IS NULL OR (
        r.test_name ILIKE ${searchPattern}
        OR r.job_name ILIKE ${searchPattern}
        OR r.cable_id ILIKE ${searchPattern}
        OR r.operator_a ILIKE ${searchPattern}
        OR r.unit_a_serial ILIKE ${searchPattern}
      ))
  `;

  return apiResponse.success(res, {
    results: rows,
    total: Number(countRows[0]?.total || 0),
    page,
    pageSize,
  });
}

async function handleStats(req: NextApiRequest, res: NextApiResponse) {
  const projectId = (req.query.projectId as string) || null;

  const stats = await sql`
    SELECT
      COUNT(*) as total,
      COUNT(*) FILTER (WHERE global_verdict = 'Pass') as passed,
      COUNT(*) FILTER (WHERE global_verdict = 'Fail') as failed,
      COUNT(*) FILTER (WHERE global_verdict IS NULL OR global_verdict NOT IN ('Pass', 'Fail')) as pending,
      COUNT(*) FILTER (WHERE test_type = 'olts') as olts_count,
      COUNT(*) FILTER (WHERE test_type = 'iolm') as iolm_count,
      COUNT(DISTINCT unit_a_serial) FILTER (WHERE unit_a_serial IS NOT NULL) as unique_equipment,
      COUNT(DISTINCT operator_a) FILTER (WHERE operator_a IS NOT NULL) as unique_operators,
      MIN(test_date_time) as earliest_test,
      MAX(test_date_time) as latest_test
    FROM exfo_test_results
    WHERE (${projectId}::UUID IS NULL OR project_id = ${projectId}::UUID)
  `;

  return apiResponse.success(res, stats[0] || {});
}

async function handleEquipment(req: NextApiRequest, res: NextApiResponse) {
  const projectId = (req.query.projectId as string) || null;

  const equipment = await sql`
    SELECT
      unit_a_serial as serial_number,
      unit_a_model as model,
      COUNT(*) as test_count,
      COUNT(*) FILTER (WHERE global_verdict = 'Pass') as pass_count,
      COUNT(*) FILTER (WHERE global_verdict = 'Fail') as fail_count,
      MIN(test_date_time) as first_test,
      MAX(test_date_time) as last_test,
      r.asset_id,
      a.name AS asset_name
    FROM exfo_test_results r
    LEFT JOIN assets a ON a.id = r.asset_id
    WHERE unit_a_serial IS NOT NULL
      AND (${projectId}::UUID IS NULL OR r.project_id = ${projectId}::UUID)
    GROUP BY unit_a_serial, unit_a_model, r.asset_id, a.name
    ORDER BY test_count DESC
  `;

  return apiResponse.success(res, { equipment });
}

async function handleProjects(res: NextApiResponse) {
  const projects = await sql`
    SELECT DISTINCT
      r.parsed_project as code,
      p.id as project_id,
      p.project_name,
      COUNT(*) as result_count
    FROM exfo_test_results r
    LEFT JOIN projects p ON p.id = r.project_id
    GROUP BY r.parsed_project, p.id, p.project_name
    ORDER BY result_count DESC
  `;

  return apiResponse.success(res, { projects });
}

export default withAuth(handler);

