/**
 * Route Types for Tab-Based Navigation
 * Core type definitions for module navigation configuration
 */

import type { LucideIcon } from 'lucide-react';

/**
 * Module identifiers for all FibreFlow modules
 */
export type ModuleId =
  | 'main'
  | 'projects'
  | 'activate'
  | 'maintenance'
  | 'procurement'
  | 'assets'
  | 'fleet'
  | 'staff'
  | 'people'
  | 'analytics'
  | 'communications'
  | 'system'
  | 'construction-qa';

/**
 * Badge types for tabs
 */
export type BadgeType = 'info' | 'warning' | 'error' | 'success';

/**
 * Tab badge configuration
 */
export interface TabBadge {
  count: number;
  type: BadgeType;
}

/**
 * Single tab configuration
 */
export interface TabConfig {
  /** Unique tab identifier */
  id: string;
  /** Display label */
  label: string;
  /** Short label for mobile/compact views */
  shortLabel?: string;
  /** Tab icon */
  icon: LucideIcon;
  /** Route path (absolute) */
  path: string;
  /** RBAC permission key for access control */
  rbacKey?: string;
  /** Nested sub-tabs (3rd level navigation) */
  subTabs?: TabConfig[];
  /** Optional badge */
  badge?: TabBadge;
  /** Hide tab from navigation */
  hidden?: boolean;
  /** Tab requires context (e.g., selected project) */
  requiresContext?: boolean;
  /** Opens in external page/tab */
  external?: boolean;
}

/**
 * Module navigation configuration
 */
export interface ModuleNavigationConfig {
  /** Unique module identifier */
  moduleId: ModuleId;
  /** Display name */
  moduleName: string;
  /** Optional description/subtitle */
  description?: string;
  /** Base path for the module */
  basePath: string;
  /** Module icon */
  icon: LucideIcon;
  /** Tab configurations */
  tabs: TabConfig[];
  /** Accent color (CSS variable name without --) */
  accentColor?: string;
  /** Show project selector in header */
  showProjectSelector?: boolean;
}

// 🟢 WORKING: Manual Teams sync trigger — admin only, fires and forgets in background
import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { fetchRecentCallRecords } from '@/lib/graph/call-records';
import { processMeetingFromCallRecord } from '@/lib/graph/meeting-processor';
import { neon } from '@neondatabase/serverless';

const sql = neon(process.env.DATABASE_URL!);

const LOGGER = 'TeamsSync';

/** Roles permitted to trigger a manual sync */
const ALLOWED_ROLES = new Set(['admin', 'super_admin']);

/** Default look-back window when `hours` is not provided in the request body */
const DEFAULT_HOURS = 24;

/**
 * POST /api/meetings/sync-teams
 *
 * Triggers a manual backfill of Teams call records from the last N hours.
 * Call records that already have a completed meeting row are skipped.
 *
 * Auth: admin or super_admin only.
 * Response: 202 Accepted immediately; processing continues in background.
 *
 * Body:
 *   hours?: number  — look-back window in hours (default: 24)
 */
async function handler(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  const authReq = req as AuthenticatedNextApiRequest;
  const userRole = authReq.user?.role;

  if (!ALLOWED_ROLES.has(userRole)) {
    return apiResponse.forbidden(res, 'Admin access required to trigger Teams sync');
  }

  const rawHours = req.body?.hours;
  const hours = rawHours !== undefined ? Number(rawHours) : DEFAULT_HOURS;

  if (isNaN(hours) || hours <= 0 || hours > 168) {
    return apiResponse.badRequest(res, 'hours must be a positive number between 1 and 168');
  }

  const since = new Date(Date.now() - hours * 60 * 60 * 1000);

  log.info(
    'Manual Teams sync triggered',
    { hours, since: since.toISOString(), triggeredBy: authReq.user?.email },
    LOGGER
  );

  // Respond 202 immediately so the caller does not wait for the full sync
  res.status(202).json({
    message: `Teams sync started for the last ${hours} hours`,
    since: since.toISOString(),
  });

  // Process in background — errors are logged, not surfaced to the caller
  setImmediate(async () => {
    try {
      const records = await fetchRecentCallRecords(since);

      log.info(
        'Teams sync: call records fetched',
        { count: records.length, since: since.toISOString() },
        LOGGER
      );

      let processed = 0;
      let skipped = 0;
      let failed = 0;

      for (const record of records) {
        // Skip records that already have a completed meeting row
        const existing = await sql`
          SELECT id
          FROM meetings
          WHERE teams_call_record_id = ${record.id}
            AND processing_status = 'completed'
        `;

        if (existing.length > 0) {
          skipped++;
          continue;
        }

        try {
          const meetingId = await processMeetingFromCallRecord(record.id);
          if (meetingId > 0) processed++;
        } catch (error: unknown) {
          failed++;
          const errorMsg = error instanceof Error ? error.message : String(error);
          log.error(
            'Teams sync: failed to process call record',
            { callRecordId: record.id, error: errorMsg },
            LOGGER
          );
        }
      }

      log.info(
        'Teams sync complete',
        { total: records.length, processed, skipped, failed },
        LOGGER
      );
    } catch (error: unknown) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      log.error('Teams sync background job failed', { error: errorMsg }, LOGGER);
    }
  });
}

export default withAuth(handler);

/**
 * AccessibleAccordion
 *
 * WCAG 2.1 AA compliant accordion (card variant).
 *
 * Implements:
 *   - aria-expanded on trigger button           (WCAG 4.1.2)
 *   - aria-controls linking button → panel      (WCAG 4.1.2)
 *   - aria-labelledby linking panel → button    (WCAG 1.3.1)
 *   - Enter / Space keyboard activation         (WCAG 2.1.1)
 *   - Focus ring on trigger                     (WCAG 2.4.7)
 *   - All interactive content keyboard reachable
 *
 * Usage:
 *   <AccessibleAccordion
 *     items={phases.map(p => ({
 *       id: p.phase,
 *       header: (expanded) => <PhaseHeader phase={p} expanded={expanded} />,
 *       body: <PhaseBody items={p.items} />,
 *     }))}
 *     expandedIds={expandedPhases}
 *     onToggle={togglePhase}
 *   />
 */

import React from 'react';
import { cn } from '@/lib/utils';

export interface AccordionItemConfig {
  id: string;
  /** Render prop — receives current expanded state so header can show ▲ / ▼ */
  header: (expanded: boolean) => React.ReactNode;
  body: React.ReactNode;
  /** Extra classes on the outer card wrapper */
  className?: string;
  /** Extra classes on the trigger button */
  headerClassName?: string;
  /** Extra classes on the body panel */
  bodyClassName?: string;
}

export interface AccessibleAccordionProps {
  items: AccordionItemConfig[];
  /** Controlled expanded state — Set of item ids that are currently open */
  expandedIds: Set<string>;
  onToggle: (id: string) => void;
  className?: string;
}

export function AccessibleAccordion({
  items,
  expandedIds,
  onToggle,
  className,
}: AccessibleAccordionProps) {
  return (
    <div className={cn('space-y-3', className)}>
      {items.map((item) => {
        const isExpanded = expandedIds.has(item.id);
        const triggerId = `accordion-trigger-${item.id}`;
        const panelId = `accordion-panel-${item.id}`;

        return (
          <div
            key={item.id}
            className={cn(
              'bg-[var(--ff-card-bg)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden',
              item.className,
            )}
          >
            {/* ── Trigger ── */}
            <button
              id={triggerId}
              type="button"
              aria-expanded={isExpanded}
              aria-controls={panelId}
              onClick={() => onToggle(item.id)}
              className={cn(
                'w-full flex items-center justify-between px-4 py-3',
                'hover:bg-[var(--ff-bg-tertiary)] transition-colors',
                'focus:outline-none focus:ring-2 focus:ring-inset focus:ring-[var(--ff-accent)]',
                item.headerClassName,
              )}
            >
              {item.header(isExpanded)}
            </button>

            {/* ── Panel ── */}
            <div
              id={panelId}
              role="region"
              aria-labelledby={triggerId}
              hidden={!isExpanded}
              className={cn('border-t border-[var(--ff-border-light)]', item.bodyClassName)}
            >
              {item.body}
            </div>
          </div>
        );
      })}
    </div>
  );
}

export default AccessibleAccordion;

'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { ChevronDown, ChevronRight } from 'lucide-react';
import type { SidebarStyles } from './types';
import type { ThemeConfig } from '@/types/theme.types';

interface CollapsibleSectionProps {
  sectionTitle: string;
  sectionId: string;
  isExpanded: boolean;
  isCollapsible: boolean;
  onToggle: (sectionId: string, shiftKey: boolean) => void;
  isCollapsed: boolean; // sidebar collapse (icons-only mode)
  sidebarStyles: SidebarStyles;
  themeConfig: ThemeConfig;
  hasActiveItem: boolean;
  children: React.ReactNode;
  sectionLink?: string; // If provided, section header becomes a direct link
  sectionIcon?: React.ComponentType<{ className?: string }>; // Icon for linked sections
}

export function CollapsibleSection({
  sectionTitle,
  sectionId,
  isExpanded,
  isCollapsible,
  onToggle,
  isCollapsed,
  sidebarStyles,
  themeConfig,
  hasActiveItem,
  children,
  sectionLink,
  sectionIcon: SectionIcon,
}: CollapsibleSectionProps) {
  const pathname = usePathname();

  const handleClick = (e: React.MouseEvent) => {
    if (isCollapsible) {
      onToggle(sectionId, e.shiftKey);
    }
  };

  // In collapsed sidebar mode (icons-only), always show items
  const showContent = isCollapsed || isExpanded || !isCollapsible;

  // Check if this linked section is active
  const isLinkActive = sectionLink && pathname?.startsWith(sectionLink);

  // If sectionLink is provided, render as a direct navigation link (no children/dropdown)
  if (sectionLink) {
    return (
      <div className={`${isCollapsed ? 'px-2' : 'px-4'} mb-4`}>
        <Link
          href={sectionLink}
          className={`w-full flex items-center gap-3 text-sm font-medium px-3 py-2.5 rounded-lg transition-colors ${
            isLinkActive
              ? 'bg-card/10 text-white'
              : 'hover:bg-card/5 text-gray-300 hover:text-white'
          }`}
          style={{
            color: isLinkActive ? themeConfig.colors.primary[400] : sidebarStyles.textColor,
            backgroundColor: isLinkActive ? `${themeConfig.colors.primary[500]}20` : undefined
          }}
        >
          {SectionIcon && <SectionIcon className="w-5 h-5 flex-shrink-0" />}
          {!isCollapsed && <span>{sectionTitle}</span>}
        </Link>
      </div>
    );
  }

  return (
    <div className={`${isCollapsed ? 'px-2' : 'px-4'} mb-4`}>
      {/* Section Header */}
      {!isCollapsed && (
        <button
          type="button"
          onClick={handleClick}
          className={`w-full flex items-center justify-between text-xs font-semibold tracking-wide mb-2 px-2 py-1 rounded transition-colors ${
            isCollapsible ? 'hover:bg-card/5 cursor-pointer' : 'cursor-default'
          }`}
          style={{ color: hasActiveItem ? themeConfig.colors.primary[400] : sidebarStyles.textColorTertiary }}
          title={isCollapsible ? (isExpanded ? 'Click to collapse, Shift+click to keep others open' : 'Click to expand') : undefined}
        >
          <span>{sectionTitle}</span>
          {isCollapsible && (
            <span className="transition-transform duration-200">
              {isExpanded ? (
                <ChevronDown className="w-3 h-3" />
              ) : (
                <ChevronRight className="w-3 h-3" />
              )}
            </span>
          )}
        </button>
      )}

      {/* Section Content with animation */}
      <div
        className={`overflow-hidden transition-all duration-200 ease-in-out ${
          showContent ? 'max-h-[1000px] opacity-100' : 'max-h-0 opacity-0'
        }`}
      >
        <div className="space-y-1">
          {children}
        </div>
      </div>
    </div>
  );
}

// 🟢 WORKING: Core orchestrator — processes a single Teams call record into a meeting row
import { neon } from '@neondatabase/serverless';
import { log } from '@/lib/logger';
import { fetchCallRecordById } from './call-records';
import {
  fetchOnlineMeetingId,
  listTranscripts,
  downloadTranscriptContent,
  parseVttSpeakers,
} from './transcripts';
import { listRecordings, downloadRecordingToDisk } from './recordings';
import { resolveParticipants } from './speaker-resolver';
import { processWithLLM } from '@/lib/llm/meeting-processor';

const sql = neon(process.env.DATABASE_URL!);

/** Transcripts larger than this are spilled to the meeting_transcripts table */
const TRANSCRIPT_INLINE_LIMIT = 500_000;

/** Minimum call duration to process (very short calls are noise) */
const MIN_DURATION_SECONDS = 60;

const LOGGER = 'MeetingProcessor';

/**
 * Processes a single Teams call record into a fully enriched meeting row.
 *
 * Execution order:
 *   1. Fetch the full call record (with sessions/segments expanded)
 *   2. Skip calls shorter than MIN_DURATION_SECONDS
 *   3. Resolve all participants via Graph /users
 *   4. Upsert the meeting row (idempotent on teams_call_record_id)
 *   5. Fetch transcript (inline or spill to meeting_transcripts)
 *   6. Download recording to disk
 *   7. Run LLM enrichment (summary, action items, topics)
 *   8. Mark status = 'completed'
 *
 * On any failure after the upsert, status is set to 'failed' with the
 * error message persisted in processing_error so ops can inspect.
 *
 * @param callRecordId - Graph callRecord ID (UUID)
 * @returns The database ID of the meeting row, or 0 if the call was skipped
 */
export async function processMeetingFromCallRecord(callRecordId: string): Promise<number> {
  // 1. Fetch full call record with sessions expanded
  const callRecord = await fetchCallRecordById(callRecordId);

  // 2. Skip calls shorter than minimum duration
  const startMs = new Date(callRecord.startDateTime).getTime();
  const endMs = new Date(callRecord.endDateTime).getTime();
  const durationSeconds = Math.floor((endMs - startMs) / 1000);

  if (durationSeconds < MIN_DURATION_SECONDS) {
    log.info(
      'Skipping short call',
      { callRecordId, durationSeconds, minRequired: MIN_DURATION_SECONDS },
      LOGGER
    );
    return 0;
  }

  // 3. Resolve participants (deduped by Graph user ID)
  const participants = await resolveParticipants(callRecord);

  const participantsJson = JSON.stringify(
    participants.map(p => ({
      name: p.displayName,
      email: p.email,
      displayName: p.displayName,
    }))
  );

  // Identify organizer from the call record organizer field
  const organizer = callRecord.organizer?.user;
  const organizerParticipant = organizer?.id
    ? participants.find(p => p.graphUserId === organizer.id) ?? null
    : null;

  // 4. Upsert meeting row — idempotent on teams_call_record_id
  const title = `Teams Meeting - ${new Date(callRecord.startDateTime).toLocaleDateString('en-ZA')}`;
  const durationMinutes = Math.floor(durationSeconds / 60);

  const rows = await sql`
    INSERT INTO meetings (
      title,
      meeting_date,
      duration,
      participants,
      source,
      teams_call_record_id,
      teams_meeting_id,
      organizer_email,
      organizer_name,
      join_url,
      processing_status,
      created_at,
      updated_at
    ) VALUES (
      ${title},
      ${callRecord.startDateTime},
      ${durationMinutes},
      ${participantsJson},
      'teams',
      ${callRecordId},
      ${callRecord.joinWebUrl ?? null},
      ${organizerParticipant?.email ?? null},
      ${organizerParticipant?.displayName ?? organizer?.displayName ?? null},
      ${callRecord.joinWebUrl ?? null},
      'fetching',
      NOW(),
      NOW()
    )
    ON CONFLICT (teams_call_record_id) DO UPDATE SET
      title              = EXCLUDED.title,
      duration           = EXCLUDED.duration,
      participants       = EXCLUDED.participants,
      organizer_email    = EXCLUDED.organizer_email,
      organizer_name     = EXCLUDED.organizer_name,
      processing_status  = 'fetching',
      processing_error   = NULL,
      updated_at         = NOW()
    RETURNING id
  `;

  const meetingId = rows[0]!.id as number;
  log.info('Meeting upserted', { meetingId, callRecordId, durationMinutes }, LOGGER);

  try {
    // 5. Fetch transcript and recording (requires joinWebUrl + a resolved organizer)
    if (callRecord.joinWebUrl && organizerParticipant) {
      const onlineMeetingId = await fetchOnlineMeetingId(
        organizerParticipant.graphUserId,
        callRecord.joinWebUrl
      );

      if (onlineMeetingId) {
        await fetchAndStoreTranscript(
          meetingId,
          organizerParticipant.graphUserId,
          onlineMeetingId
        );

        await fetchAndStoreRecording(
          meetingId,
          organizerParticipant.graphUserId,
          onlineMeetingId
        );
      }
    }

    // 6. LLM enrichment
    await sql`UPDATE meetings SET processing_status = 'processing', updated_at = NOW() WHERE id = ${meetingId}`;
    await processWithLLM(meetingId);

    // 7. Mark complete
    await sql`
      UPDATE meetings
      SET processing_status = 'completed',
          processed_at      = NOW(),
          updated_at        = NOW()
      WHERE id = ${meetingId}
    `;

    log.info('Meeting processing complete', { meetingId }, LOGGER);
    return meetingId;
  } catch (error: unknown) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    log.error('Meeting processing failed', { meetingId, error: errorMsg }, LOGGER);

    await sql`
      UPDATE meetings
      SET processing_status = 'failed',
          processing_error  = ${errorMsg},
          updated_at        = NOW()
      WHERE id = ${meetingId}
    `;

    throw error;
  }
}

/**
 * Fetches the transcript for an online meeting and persists it.
 * Transcripts under TRANSCRIPT_INLINE_LIMIT are stored inline on the meetings row.
 * Larger transcripts are written to the meeting_transcripts table.
 */
async function fetchAndStoreTranscript(
  meetingId: number,
  organizerUserId: string,
  onlineMeetingId: string
): Promise<void> {
  const transcripts = await listTranscripts(organizerUserId, onlineMeetingId);

  if (transcripts.length === 0) {
    log.info('No transcripts available', { meetingId, onlineMeetingId }, LOGGER);
    return;
  }

  // Take the most recent transcript (first in list from Graph)
  const vtt = await downloadTranscriptContent(
    organizerUserId,
    onlineMeetingId,
    transcripts[0]!.id
  );

  if (vtt.length <= TRANSCRIPT_INLINE_LIMIT) {
    await sql`UPDATE meetings SET raw_transcript = ${vtt}, updated_at = NOW() WHERE id = ${meetingId}`;
  } else {
    // Spill to meeting_transcripts; store first 50 speakers in speaker_map for quick lookup
    const speakerMap = JSON.stringify(parseVttSpeakers(vtt).slice(0, 50));
    await sql`
      INSERT INTO meeting_transcripts (meeting_id, format, content, speaker_map, created_at)
      VALUES (${meetingId}, 'vtt', ${vtt}, ${speakerMap}, NOW())
      ON CONFLICT (meeting_id) DO UPDATE SET
        content    = EXCLUDED.content,
        speaker_map = EXCLUDED.speaker_map
    `;
  }

  log.info('Transcript stored', { meetingId, size: vtt.length }, LOGGER);
}

/**
 * Downloads the first recording for an online meeting and persists the path + size.
 */
async function fetchAndStoreRecording(
  meetingId: number,
  organizerUserId: string,
  onlineMeetingId: string
): Promise<void> {
  const recordings = await listRecordings(organizerUserId, onlineMeetingId);

  if (recordings.length === 0) {
    log.info('No recordings available', { meetingId, onlineMeetingId }, LOGGER);
    return;
  }

  const { filePath, sizeBytes } = await downloadRecordingToDisk(
    organizerUserId,
    onlineMeetingId,
    recordings[0]!.id,
    meetingId
  );

  await sql`
    UPDATE meetings
    SET recording_path        = ${filePath},
        recording_size_bytes  = ${sizeBytes},
        updated_at            = NOW()
    WHERE id = ${meetingId}
  `;

  log.info('Recording stored', { meetingId, filePath, sizeBytes }, LOGGER);
}

