  captured_at: string | null; // ISO timestamp (EXIF)
  gps_lat: number | null;
  gps_lon: number | null;
  /** QField username or technician phone number. */
  captured_by: string | null;

  created_at: string; // ISO timestamp
  updated_at: string; // ISO timestamp
}

