                        onSelect={() => handleSelectPon(zone.zone_no, pon.pon_no)}
                      />
                    ))
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Selected PON feature table */}
      {selectedPon && (
        <PonFeaturesPanel
          projectId={projectId}
          zoneNo={selectedPon.zone}
          ponNo={selectedPon.pon}
          highlightId={highlightId}
        />
      )}
    </div>
  );
}

